const e={lang:"af",source:"src/constants/lessonData.js",lessons:81,hash:{1:"80c0d50a",2:"7a0ec9a6",3:"5e407f05",4:"c9cd9cb3",5:"5c610420",6:"b4a6b648",7:"d66596d0",8:"796196ca",9:"6c2a6709",10:"8cdd1852",11:"747d9b20",12:"5b50c1ca",13:"5dd950f1",14:"de4e5bbf",15:"5db03e62",16:"820d4185",17:"d3349e94",18:"f7903ca3",19:"4fd21613",20:"cb2b025c",21:"392f93bc",22:"846dbcdf",23:"70df8bf3",24:"318d2051",25:"7dc72b96",26:"e338834b",27:"a5f9340e",28:"650ed568",29:"1d51c7b0",30:"29dba498",31:"390a64a0",32:"424ee5ad",33:"4d7d49b0",34:"fb5f9b39",35:"c5bdaa40",36:"e09ff28e",37:"c48e70c0",38:"eb1e4f5a",39:"881a67f4",40:"bf4399f2",41:"c4f52986",42:"551af277",43:"d87240fc",44:"2b7b683e",45:"a3dd8868",46:"7873826b",47:"0ba85d7e",48:"6d2df7b4",49:"c1055330",50:"789af852",51:"27e927d2",52:"041c444d",53:"8fb1d4bc",54:"2352615a",55:"b7571fb2",56:"f20ea6ce",57:"736fbba1",58:"d6965200",59:"c736a610",60:"6db8d44d",61:"eec64988",62:"0171d5b9",63:"606ebf4a",64:"70769bc6",65:"94423ba8",66:"e27a40f2",67:"8c29d099",68:"5ce307ea",69:"91203966",70:"c07c9a34",71:"3605b239",72:"960b5a23",73:"2f6ccb1d",74:"1041cf9e",75:"9544722a",76:"c8fc8849",77:"f40ce1e9",78:"402722ee",79:"2b4439e3",80:"17168e74",81:"cc389c02"}},n=JSON.parse(`{"1":{"title":"Wat is 'n Aandeel?","desc":"Besit 'n klein stukkie van 'n maatskappy","content":"Stel jou voor jy en 9 vriende gooi elkeen {c}10 in om saam 'n paar tekkies van {c}100 te koop. Elkeen van julle besit 1/10 van daardie tekkies — dit is basies 'n aandeel! Wanneer jy 'n aandeel in {retail} koop, besit jy 'n klein skyfie van elke winkel, elke produk en elke {cName} wat hulle maak. Hoe groter die maatskappy groei, hoe meer is jou skyfie werd! 🔥","quiz":{"q":"Jy en 4 vriende deel die koste van 'n {c}500 gaming-stoel gelykop. Wat besit elkeen van julle?","options":["1/5 (20%) van die stoel elk","Niks — net een persoon kan dit besit","Die hele stoel saam, sonder enige individuele aandeel"]}},"2":{"title":"Die {ex} Verduidelik","desc":"{name} se aandelebeurs","content":"Dink aan die {ex} ({exFull}) soos 'n reusagtige aanlyn mark — behalwe dat mense, in plaas van tekkies of fone, klein stukkies (aandele) van maatskappye soos {top5} koop en verkoop. Dit is elke weeksdag oop, behalwe op openbare vakansiedae, en die pryse verander heeldag op grond van wie koop en wie verkoop. Die {ex} is {exDesc}! 🌍","quiz":{"q":"Waarmee stem die {ex} die meeste ooreen?","options":["'n Spaarrekening by 'n bank","'n Selfoongeld-app","'n Mark waar jy stukkies van maatskappye koop en verkoop"]}},"3":{"title":"Bulle teen Bere","desc":"Markrigtings ontsyfer","content":"In die markte swaai diere die septer 😄\\n\\n🐂 Bul = pryse gaan OP. Stel jou 'n bul voor wat met sy horings opwaarts storm. Almal wen, mense koop, lekker vibes.\\n\\n🐻 Beer = pryse gaan AF. Stel jou 'n beer voor wat met sy poot afwaarts klap. Mense is bang, hulle verkoop, nie 'n lekker tyd nie.\\n\\nWanneer iemand sê 'Ek is bullish oor {tech}' — dan dink hulle die prys gaan opgaan. Wanneer hulle 'bearish' sê — dan dink hulle dit gaan af. Jy sal hierdie woorde oral in finansies hoor!","quiz":{"q":"Jou vriend sê: 'Ek is bearish oor {telco} hierdie week.' Wat beteken dit?","options":["Hulle dink {telco} se prys gaan opgaan","Hulle dink {telco} se prys gaan afgaan","Hulle wil soveel {telco} as moontlik koop"]}},"4":{"title":"Wat is 'n Makelaar?","desc":"Jou toegang tot die koop van aandele","content":"Jy kan nie sommer by {retail} instap en sê 'gee my asseblief 'n stukkie van julle maatskappy' nie 😂 Jy het 'n makelaar nodig — 'n app of diens wat kopers en verkopers op die aandelebeurs verbind.\\n\\nDink aan 'n makelaar soos {shop}. Jy wil iets hê, {shop} verbind jou daarmee — hulle hanteer die transaksie en vra 'n klein fooi. Gewilde makelaars in {name} sluit {broker} en ander in.\\n\\nHier is wat 'n makelaar NIE doen nie: besluit watter aandele opgaan. Hulle gee jou order deur aan die mark. Die prys beweeg oor wat almal daar buite koop en verkoop — nie omdat jou makelaar so gesê het nie.\\n\\nMakelaars publiseer wel menings. Hulle ontleders gradeer aandele as 'koop', 'hou' of 'verkoop'. 'n Mening is nie 'n bevel nie 🤷 Ontleders verskil openlik van mekaar oor presies dieselfde aandeel, en baie van hulle is uiteindelik verkeerd. Lees 'n gradering soos 'n resensie, nie soos 'n reël nie.\\n\\nNoobTrader leer jou presies hoe dit werk — gratis, met virtuele geld!","quiz":{"q":"Hoekom het jy 'n makelaar nodig om aandele te koop?","options":["Makelaars besluit watter aandele opgaan","Jy moet hulle betaal voordat jy geld kan verdien","Hulle verbind kopers en verkopers op die aandelebeurs"]}},"5":{"title":"Aandeelprys-grondbeginsels","desc":"Hoekom gaan pryse op en af?","content":"Al ooit opgemerk hoe beperkte-uitgawe-tekkies se prys skiet wanneer hulle vrygestel word? Dieselfde gebeur met aandele — dit gaan alles oor vraag en aanbod.\\n\\n📈 Baie mense WIL koop → prys gaan OP\\n📉 Baie mense WIL verkoop → prys gaan AF\\n\\nAs {telco} aankondig dat hulle 10 miljoen nuwe kliënte kry, wil almal 'n stukkie hê — die prys skiet op. As hulle 'n groot verlies rapporteer, verkoop mense in paniek — die prys val. Nuus, resultate en selfs sosialemedia-neigings kan aandeelpryse onmiddellik beweeg!","quiz":{"q":"{retail} kondig rekordwinste aan en beplan om 50 nuwe winkels oop te maak. Wat gebeur waarskynlik met hulle aandeelprys?","options":["Dit gaan op namate meer mense wil koop","Dit bly presies dieselfde","Dit stort ineen omdat hulle geld aan winkels bestee"]}},"6":{"title":"Lees 'n Prysgrafiek","desc":"Kerse, lyne en wat hulle beteken","content":"'n Prysgrafiek is soos 'n hoogtepunte-video van 'n aandeel se geskiedenis. Die gewildste soort is 'n kandelaargrafiek — elke 'kers' wys jou 4 dinge vir een dag:\\n\\n🟢 Groen kers = die prys het daardie dag OPgegaan (laer oopgemaak, hoër gesluit)\\n🔴 Rooi kers = die prys het AFgegaan (hoër oopgemaak, laer gesluit)\\n📏 Die dun lyne bo en onder = die hoogste en laagste pryse van die dag\\n\\nAs jy baie groen kerse agtermekaar sien — dit is 'n sterk opwaartse neiging. Baie rooi kerse — 'n afwaartse neiging. Om grafieke te leer lees is soos om 'n speletjie se telbord te leer lees! 🎮","quiz":{"q":"Jy sien 5 rooi kerse agtermekaar op 'n grafiek. Wat sê dit vir jou?","options":["Die aandeel styg al 5 dae lank","Die aandeel val al 5 dae lank","Die aandeelprys het glad nie verander nie"]}},"7":{"title":"Volume & Wat Dit Jou Vertel","desc":"Hoeveel aandele verhandel word","content":"Volume = hoeveel aandele op 'n dag gekoop en verkoop is. Dink daaraan soos kykers op 'n TikTok-video.\\n\\n🔊 HOË volume = baie mense verhandel. As die prys met hoë volume beweeg, is dit 'n sterker, meer betroubare sein — soos 'n video wat regtig viraal gaan, nie deur bots nie.\\n\\n🔇 LAE volume = net 'n paar mense verhandel. Pryse kan vreemd beweeg wanneer die volume laag is — soos 'n video met net 3 kykers wat per ongeluk gedeel word.\\n\\nKyk altyd na die volume wanneer jy 'n groot prysbeweging sien — dit vertel jou of die beweging eg is of net geraas!","quiz":{"q":"{telco} se aandeel spring vandag 5%, maar die volume is baie laag. Wat behoort jy te dink?","options":["Dit is beslis 'n groot geleentheid — koop nou!","Lae volume beteken altyd die prys sal aanhou styg","Die beweging is dalk nie betroubaar nie — lae volume maak dit verdag"]}},"8":{"title":"Steun & Weerstand","desc":"Prysvlakke wat saak maak","content":"Stel jou voor 'n aandeel se prys is 'n bonsbal:\\n\\n🧱 STEUN = die vloer waarvan die bal terugbons. Die prys val en val, maar elke keer as dit hierdie vlak tref, bons dit terug op. Baie kopers daag hier op.\\n\\n🪟 WEERSTAND = die plafon wat die bal tref. Elke keer as die prys tot by hierdie vlak styg, word dit teruggestoot. Baie verkopers vat hier hulle wins.\\n\\nHandelaars gebruik hierdie vlakke soos 'n speletjie se kaart — koop naby die vloer, verkoop naby die plafon. Wanneer die prys uiteindelik deur weerstand breek, skiet dit dikwels vinnig op. Wanneer dit deur steun breek — maak reg vir 'n val! 💥\\n\\nEen eerlike waarskuwing: hierdie vlakke word deur mense geteken wat na grafieke kyk, dit is nie reëls wat die mark moet gehoorsaam nie. 'n Aandeel kan reguit deur 'steun' bars en net aanhou val. 📉","quiz":{"q":"'n Aandeel het drie keer by {c}50 teruggebons sonder om ooit laer te gaan. Wat word {c}50 genoem?","options":["'n Steunvlak","'n Weerstandsvlak","Die plafonprys"]}},"9":{"title":"Diversifikasie","desc":"Moenie al jou eiers in een mandjie sit nie","content":"Stel jou voor jy bestee AL jou databundel aan een stroom-app. Dan gaan daardie app af. Nou sit jy met niks. 😩\\n\\nMaar as jy jou data oor WhatsApp, YouTube ÉN jou stroom-app versprei — dan ruïneer een wat afgaan nie jou hele vibe nie.\\n\\nDieselfde geld vir belegging! As jy AL jou geld in een aandeel sit en dit stort, verloor jy alles. Maar as jy dit versprei oor {telco} (telekommunikasie), {retail} (kleinhandel), {tech} (tegnologie) en 'n ETF — dan sink een ineenstorting nie jou hele portefeulje nie. Hierdie verspreidingstrategie word DIVERSIFIKASIE genoem. 💼","quiz":{"q":"Jy het {c}500 om te belê. Watter benadering is veiliger?","options":["Sit al {c}500 in een maatskappy waarvan jy hou","Hou dit as kontant — belegging is te riskant","Verdeel {c}500 oor 5 verskillende maatskappye in verskillende bedrywe"]}},"10":{"title":"Risiko & Beloning","desc":"Hoekom beteken groter winste groter risiko","content":"Al ooit 'n verrassingsboks gekoop? Jy kry dalk iets ongelooflik — of pure gemors. Dit is hoë risiko / hoë beloning.\\n\\nBelegging werk presies so:\\n\\n✅ LAER RISIKO, LAER BELONING: Soos {retail} — reusagtige maatskappy, goed gevestig. Jou geld groei gewoonlik stadig en bestendig. Let op 'laer', nie 'geen' nie — groot maatskappye val ook.\\n\\n🎲 HOË RISIKO, HOË BELONING: Soos 'n piepklein nuwe mynmaatskappy. Dit kan 10x word — of heeltemal verdwyn. Nes die verrassingsboks.\\n\\nVoor jy in enigiets belê, vra altyd: 'Wat is die ergste wat kan gebeur?' As jy dit nie kan bekostig om te verloor nie, moenie die risiko vat nie!","quiz":{"q":"'n Piepklein nuwe kripto waarvan niemand nog gehoor het nie belowe 500% opbrengs. Wat is die eerlike waarheid?","options":["Dit is beslis eg — 'n hoër opbrengs beteken altyd 'n beter belegging","Hoe hoër die belowe opbrengs, hoe hoër die risiko om alles te verloor","Kripto klop altyd {ex}-aandele"]}},"11":{"title":"Langtermyn teenoor Korttermyn","desc":"Beleggings- teenoor verhandelingsdenke","content":"🏃 KORTTERMYNVERHANDELING: Koop en verkoop binne dae of weke om vinnige prysbewegings te vang. Hoë stres, verg baie skermtyd. Soos om te probeer voorspel wie elke wedstryd in 'n toernooi wen.\\n\\n🧘 LANGTERMYNBELEGGING: Koop aandele en hou hulle jare lank. Jy ry die duike uit en laat jou geld groei. Soos om te wed watter span die hele seisoen wen — jy raak nie paniekerig ná een slegte wedstryd nie.\\n\\nStudies van werklike makelaarsrekeninge kry oor en oor dieselfde patroon: hoe meer gereeld mense verhandel, hoe swakker vaar hulle gewoonlik sodra die koste bygereken word.\\n\\nEn jy het die een ding wat geen 40-jarige belegger kan koop nie — dekades se tyd waarin saamgestelde groei vir jou kan werk. ⏳","quiz":{"q":"Hoekom het tieners eintlik 'n voordeel bo ouer beleggers?","options":["Tieners het meer tyd sodat hulle beleggings deur saamgestelde groei kan groei","Tieners is slimmer met geld","Tieners betaal minder fooie"]}},"12":{"title":"{dcaTitle}","desc":"Belê gereeld dieselfde bedrag","content":"Hier is 'n strategie so eenvoudig dat dit skaars soos een voel — en dit vee die moeilikste vraag in belegging uit:\\n\\nBelê ELKE maand DIESELFDE bedrag — of pryse op of af is. Soos om elke enkele maand {c}100 uit jou verjaardaggeld of sakgeld eenkant te sit.\\n\\n📉 Wanneer pryse LAAG is → koop jou {c}100 MEER aandele\\n📈 Wanneer pryse HOOG is → koop jou {c}100 MINDER aandele\\n\\nMettertyd word jou gemiddelde koste per aandeel gladder — jy 'koop die duik' outomaties sonder om eers te probeer! Dit word {dcaTitle} ({dcaAbbrev}) genoem. Dit haal emosie uit belegging uit, want jy hoef nooit te besluit 'is NOU die regte tyd?' nie — jy verbind jou net en gaan aan! 💪\\n\\nReguit gepraat: dit sal nie altyd 'n enkelbedrag klop wat jy alles op een slag insit nie. Wat dit wel doen, is om 'n plan te maak waarby jy werklik kan hou.","quiz":{"q":"Jy belê {c}200 elke maand, ongeag die prys. Een maand is die aandeel goedkoop, die volgende maand duur. Wat is die voordeel?","options":["Jy koop altyd teen die laagste prys","Jy maak net geld wanneer pryse styg","Jy middel jou koste oor tyd uit en haal emosie uit belegging"]}},"13":{"title":"Geldbabas 💸","desc":"Kry betaal net omdat jy aandele hou","content":"Stel jou voor jy besit 'n verkoopmasjien. Elke week koop mense versnaperinge by JOU masjien, en jy tel die kontant op — net omdat jy dit besit. Jy hoef niks ekstra te doen nie!\\n\\nDit is wat dividende is. Ons noem hulle Geldbabas 🍼 want jou geld kry letterlik babas — klein kontantbetalings wat in jou rekening land net omdat jy aandele besit.\\n\\nGroot maatskappye soos {divPayers} betaal gereeld Geldbabas. Hoe meer aandele jy hou, hoe groter jou babas!\\n\\n⚠️ Hulle is NIE gewaarborg nie. 'n Maatskappy besluit elke keer of dit gaan betaal, en dit kan die dividend sny of heeltemal stopsit wanneer sake moeilik raak. 'n Groot uitbetaling vanjaar is geen belofte van een volgende jaar nie.\\n\\nEn as jy daardie babas herbelê om MEER aandele te koop... dan is jou volgende lot nog groter. Dit is 'n pragtige siklus 🔁","quiz":{"q":"{bank} betaal jou {c}5 vir elke aandeel wat jy besit, net omdat jy die aandele hou. Wat word hierdie betaling genoem?","options":["'n Dividend (Geldbaba)","'n Verhandelingsfooi","'n Bonus omdat jy 'n kliënt is"]}},"14":{"title":"Saamgestelde Rente","desc":"Hoe jou geld op sy eie groei","content":"Hier is die kragtigste geldgeheim wat jy ooit sal leer. Gereed? 👀\\n\\nJy belê {c}1,000 teen 10% per jaar:\\n• Jaar 1: {c}1,000 → {c}1,100 (het {c}100 verdien)\\n• Jaar 2: {c}1,100 → {c}1,210 (het {c}110 verdien — meer as jaar 1!)\\n• Jaar 3: {c}1,210 → {c}1,331 (het {c}121 verdien)\\n\\nJy verdien nou rente op jou RENTE. Die sneeubal word elke jaar groter sonder dat jy iets ekstra bysit. Ná 30 jaar teen 10%? Daardie {c}1,000 word {c}17,449! 🤯\\n\\nJy sal hoor mense noem dit 'die agtste wonder van die wêreld' en skryf dit aan Einstein toe. Daar is geen egte bewys dat hy dit ooit gesê het nie — maar die wiskunde is die deel wat saak maak, en die wiskunde is eg. Begin vroeg, en tyd doen die swaar werk vir jou.","quiz":{"q":"Jy belê {c}500 teen 10% per jaar en raak dit nooit aan nie. Waarop verdien jy in Jaar 2 rente?","options":["Net op jou oorspronklike {c}500","Jou {c}500 PLUS die rente wat in Jaar 1 verdien is","Net op die rente, nie op jou oorspronklike geld nie"]}},"15":{"title":"Saamgestelde Groei & Aandele","desc":"Herbelê Geldbabas vir groei","content":"Onthou jy Geldbabas (dividende)? Hier raak dit interessant 🤯\\n\\nNormaal: Jy verdien {c}50 aan Geldbabas → koop versnaperinge daarmee → klaar.\\n\\nSlim skuif: Jy verdien {c}50 aan Geldbabas → koop MEER aandele → volgende keer kry jy MEER Geldbabas → koop nog meer aandele → die sneeubal gaan 🔝\\n\\nDit is saamgestelde groei toegepas op aandele. Kyk na die syfers: sit 30 jaar lank elke maand dieselfde bedrag in teen 'n gemiddelde opbrengs van 10%, en jy eindig met omtrent SES KEER wat jy werklik ingesit het. Sowat vyf sesdes van daardie hoop is groei — geld wat jy nooit verdien, gespaar of gedeponeer het nie.\\n\\nOor lang tydperke het herbelegde dividende 'n groot deel van beleggers se totale opbrengs uitgemaak. Dit is presies hoekom 'vervelige' dividendbetalers glad nie vervelig blyk te wees nie 💰","quiz":{"q":"In plaas daarvan om jou {c}80 aan dividende te spandeer, gebruik jy dit om meer aandele te koop. Wat gebeur nou?","options":["Jy kry volgende keer minder dividende omdat jy hulle bestee het","Dividende hou op as jy hulle herbelê","Jy besit nou meer aandele, so jy verdien volgende keer nog MEER dividende"]}},"16":{"title":"Die Reël van 72","desc":"Vinnige manier om verdubbelingstyd te skat","content":"Hier is 'n kode-truuk vir jou brein 🧠\\n\\nWil jy weet hoe lank dit neem om jou geld te VERDUBBEL? Deel net 72 deur jou jaarlikse opbrengs:\\n\\n• 72 ÷ 12% opbrengs = 6 jaar om te verdubbel\\n• 72 ÷ 8% opbrengs = 9 jaar om te verdubbel\\n• 72 ÷ 6% opbrengs = 12 jaar om te verdubbel\\n\\nSo as jy 'n bestendige 12% per jaar op {c}2,000 verdien, het jy oor 6 jaar {c}4,000. Wag nog 6 jaar — {c}8,000. Nog 6 — {c}16,000! 🤯\\n\\nDit is 'n skatting, nie 'n wet nie — en werklike opbrengste is nooit elke jaar dieselfde bestendige syfer nie. Maar dit is naby genoeg om in jou kop te doen, en dit is juis die punt.\\n\\nDit is hoekom dit ENORM is om op 13 of 14 te begin. Jy het meer verdubbelingsiklusse voor jou as byna enigiemand anders!","quiz":{"q":"Jy verdien 8% per jaar op jou belegging. Hoeveel jaar neem dit om jou geld te verdubbel, volgens die Reël van 72?","options":["9 jaar","8 jaar","72 jaar"]}},"17":{"title":"Markorders teenoor Limietorders","desc":"Twee maniere om aandele te koop","content":"Daar is twee hoofmaniere om 'n aandeel te koop:\\n\\n⚡ MARKORDER: 'Koop nou, teen watter prys ook al.' Soos om iets in die mandjie te sit en dadelik op {shop} uit te teken — jy kry dit onmiddellik, maar die prys wat jy werklik betaal is wat die mark jou gee, en dit kan verskil van die syfer wat jy pas op die skerm gesien het.\\n\\n🎯 LIMIETORDER: 'Koop net as die prys tot {c}X val.' Soos om 'n item op jou {shop}-verlanglys te sit en vir 'n uitverkoping te wag. Jy beheer die prys — maar die transaksie gebeur dalk nooit nie.\\n\\nLimietorders gee jou beheer oor die prys. Markorders gee jou sekerheid dat dit deurgaan. Jy kan nie albei hê nie! 💸","quiz":{"q":"Jy wil {tech}-aandele koop, maar net as hulle van {c}200 na {c}180 val. Watter ordertipe gebruik jy?","options":["Markorder — koop nou teen {c}200","Limietorder — stel die teiken op {c}180 en wag","Jy kan nie 'n spesifieke koopprys stel nie"]}},"18":{"title":"Verhandelingsfooie & Koste","desc":"Verstaan verhandelingsfooie","content":"Die meeste transaksies kos jou 'n bietjie — die makelaar vat 'n klein snytjie. Dit word verhandelingsfooie of makelaarsfooie genoem.\\n\\n⚠️ Sommige makelaars adverteer 'nul kommissie'. Hulle moet steeds êrens geld maak, so hulle maak dit elders — gewoonlik uit die klein gaping tussen die koopprys en die verkoopprys, uit valutaomskakeling, of uit rente op die kontant wat in jou rekening lê. Gratis is selde gratis.\\n\\nIn NoobTrader is die gesimuleerde fooie:\\n• {ex}-aandele: {exFee} per transaksie\\n• Wêreldwye aandele: 0.50%\\n• ETF's: 0.30%\\n• Kripto: 0.60%\\n• Forex: 0.05%\\n• Kommoditeite: 0.40%\\n\\nVoorbeeld: Jy koop {c}1,000 se {retail}-aandele teen {exFee}. Die fooi is {c}{feeAmt}, so jy bestee eintlik {c}{feeTotal}.\\n\\nKlein fooie tel VINNIG op as jy dikwels verhandel. Iemand wat 20 transaksies per maand doen, betaal daardie fooi 20 keer — en betaal dit weer op pad uit. Dit is een van die redes hoekom langtermynbeleggers minder verhandel: minder transaksies, minder fooie 🧮","quiz":{"q":"Jy koop {c}1,000 se {ex}-aandele met 'n {exFee}-fooi. Hoeveel is die fooi?"}},"19":{"title":"Stop-verlies-orders","desc":"Beskerm jouself teen groot verliese","content":"'n Stop-verlies is soos om 'n limiet te stel op hoeveel jy bereid is om te verloor — 'n veiligheidsnet wat jy vooraf opstel.\\n\\nVoorbeeld: Jy koop {telco}-aandele teen {c}100 elk. Jy besluit jy wil NOOIT meer as 15% verloor nie. So jy stel 'n stop-verlies op {c}85.\\n\\nAs {telco} tot {c}85 val → word 'n verkooporder outomaties afgevuur. Jy hoef nie te sit en kyk nie, en jy hoef nie die besluit te neem terwyl jy paniekerig is nie.\\n\\n⚠️ Belangrik: 'n stop-verlies sneller 'n VERKOOP, dit waarborg nie 'n PRYS nie. As slegte nuus oornag tref en die aandeel op {c}70 oopmaak sonder om ooit teen {c}85 te verhandel, word jou order gevul teen wat die mark werklik gaan betaal. Dit kan ver onder die vlak wees wat jy gestel het.\\n\\nSonder enige stop-verlies hou jy dalk vas en hoop dit herstel... en kyk hoe dit tot {c}20 val. 😬\\n\\nWenk: Besluit altyd VOOR jy koop wat jou maksimum verlies is. Moenie emosie daardie besluit laat neem terwyl die prys reeds duik nie! 🧘","quiz":{"q":"Jy koop aandele teen {c}200 en stel 'n stop-verlies op {c}170. Wat gebeur as die prys tot {c}170 val?","options":["'n Verkooporder word outomaties gesneller om jou verlies te beperk","Jy koop outomaties meer aandele","Niks — 'n stop-verlies maak net vir wins saak"]}},"20":{"title":"Wanneer om te Koop & Verkoop","desc":"Tydsberekening, geduld en dissipline","content":"Die grootste fout wat nuwe beleggers maak? Koop wanneer almal opgewonde is en verkoop wanneer almal paniekerig is. Dit is letterlik die teenoorgestelde van wat werk. 🤦\\n\\n📱 Wanneer jou groepskletsie 'KOOP HIERDIE AANDEEL NOU!!!!' spam → is die opgewondenheid gewoonlik reeds in die prys ingereken. Jy is laat.\\n\\n😱 Wanneer almal in paniek verkoop → is dit soms wel 'n kans om teen 'n afslag te koop. Soms val die prys nog 'n jaar lank verder. Niemand lui 'n klokkie by die bodem nie.\\n\\nDie geheim? Hê 'n plan VOOR jy belê:\\n• Hoekom koop ek dit? (navorsing, nie hype nie)\\n• Teen watter prys verkoop ek as dit OP gaan? (neem wins)\\n• Teen watter prys verkoop ek as dit AF gaan? (stop-verlies)\\n\\nHou by jou plan. Moenie jou gevoelens jou strategie laat oorneem nie! 💪","quiz":{"q":"Jou hele groepskletsie hype 'n aandeel wat vanmaand reeds 80% op is. Wat is die slim skuif?","options":["Koop dadelik — die groep is altyd reg","Verkoop alles anders en gaan alles in","Doen eers jou eie navorsing; hype beteken gewoonlik die beweging is reeds verby"]}},"21":{"title":"Wat is Markkapitalisasie?","desc":"Hoe om maatskappygrootte te meet","content":"Markkapitalisasie vertel jou hoe groot 'n maatskappy werklik is — in {cPlural}.\\n\\n📐 Formule: Aandeelprys × Totale Aantal Aandele = Markkapitalisasie\\n\\nVoorbeeld: As {retail} 1 miljard aandele het en elke aandeel {c}50 kos, is die markkapitalisasie {c}50 MILJARD. Dit is die 'pryskaartjie' op die hele maatskappy.\\n\\n🔵 Groot kap: die grootste, mees gevestigde name — soos {tech} en {bank}. Laer risiko, gewoonlik stadiger groei.\\n🟡 Middelkap: mediumgrootte maatskappye. Gebalanseerde risiko.\\n🔴 Klein kap: piepklein maatskappye. Kan vinnig groei OF hard val.\\n\\n⚠️ Die afsnypunte is nie universeel nie. In die VSA beteken 'groot kap' gewoonlik iets bo $10 miljard — maar elke mark stel sy eie bande, so 'n groot kap in {name} is nie dieselfde grootte as 'n groot kap in die VSA nie. Lees die werklike syfer, nie net die etiket nie 🧐","quiz":{"q":"'n Maatskappy het 10 miljoen aandele en elke aandeel kos {c}50. Wat is die markkapitalisasie?","options":["{c}50 miljoen","{c}500 miljoen","{c}5 miljard"]}},"22":{"title":"Die P/E-verhouding Verduidelik","desc":"Is 'n aandeel duur of goedkoop?","content":"Die P/E-verhouding (Prys-tot-Verdienste) vertel jou hoeveel jy betaal vir elke {cName} van 'n maatskappy se wins.\\n\\n📐 Formule: Aandeelprys ÷ Verdienste Per Aandeel = P/E-verhouding\\n\\nDink daaraan soos die prys per skyf pizza 🍕\\n\\nAs pizza A {c}80 kos vir 8 skywe = {c}10/skyf\\nAs pizza B {c}100 kos vir 5 skywe = {c}20/skyf\\n\\nPizza A is goedkoper per skyf. Dieselfde idee geld vir aandele:\\n• Lae P/E (onder 10) = moontlik 'n winskoop — OF die mark verwag dat sy winste gaan VAL. 'n Lae P/E is 'n vraag, nie 'n antwoord nie.\\n• Hoë P/E (bo 25) = die mark verwag groot toekomstige groei. Die maatskappy moet dit dan werklik lewer.\\n\\nVergelyk P/E altyd met ANDER maatskappye in dieselfde bedryf — moenie 'n bank se P/E met 'n tegnologiemaatskappy s'n vergelyk nie!","quiz":{"q":"Maatskappy A het 'n P/E van 8. Maatskappy B (dieselfde bedryf) het 'n P/E van 30. Wat dui dit aan?","options":["Maatskappy A is goedkoper per eenheid wins — maar vind uit HOEKOM voor jy koop","Maatskappy B is altyd die beter belegging","Die P/E-verhouding help nie met beleggingsbesluite nie"]}},"23":{"title":"Lees Maatskappyresultate","desc":"Inkomste, wins en wat saak maak","content":"Elke paar maande publiseer maatskappye hulle 'rapport' — elke kwartaal in sommige markte, twee keer 'n jaar in ander — en dit beweeg aandeelpryse GROOT. Hier is waarna om te kyk:\\n\\n📊 INKOMSTE: Die totale geld wat uit verkope inkom. Soos hoeveel 'n klein winkel altesaam ingevat het.\\n💰 NETTOWINS: Wat oorbly NADAT alle uitgawes betaal is. Die werklike opbrengs aan die einde van die dag.\\n📈 VPA (Verdienste Per Aandeel): Wins gedeel deur die aantal aandele. Hoeveel elke aandeel verdien het.\\n\\nGoeie tekens: Inkomste OP + Wins OP + VPA groei = 🟢 die prys styg dikwels\\nSlegte tekens: Inkomste AF + Wins val = 🔴 die prys val dikwels\\n\\nEen vangplek: wat die prys werklik beweeg, is die resultaat teenoor wat die mark VERWAG het. Wonderlike syfers wat onder verwagting was, kan 'n aandeel steeds laat val.\\n\\n'n Maatskappy kan baie inkomste hê maar geen wins nie (hoë koste). Kyk altyd na ALBEI!","quiz":{"q":"{bank} rapporteer inkomste 15% op maar wins 20% af weens hoër koste. Is dit 'n goeie of slegte teken?","options":["Goed — inkomste is op, dit is al wat saak maak","Uitstekend — enige groei is positief","Gemeng/sleg — hulle maak meer verkope maar hou minder geld oor"]}},"24":{"title":"Sektore & Bedrywe","desc":"Verskillende soorte maatskappye","content":"Die aandelemark is in sektore verdeel — soos verskillende departemente in 'n skool.\\n\\n{sectorList}\\n\\nVerskillende sektore styg en val op verskillende tye — dit is juis die punt daarvan om oor hulle heen te diversifiseer! As bankwese ineenstort, is tegnologie dalk aan die opkom. Jou portefeulje bly gebalanseerd. 🎯","quiz":{"q":"Rentekoerse in {name} styg skerp. Watter sektor trek gewoonlik die meeste voordeel?","options":["Kleinhandel — mense sal meer bestee","Bankwese — banke verdien gewoonlik 'n wyer gaping tussen wat hulle leners vra en wat hulle spaarders betaal","Tegnologie — apps word goedkoper"]}},"25":{"title":"Wat is 'n ETF?","desc":"Koop 'n hele mandjie in een slag","content":"Vroeër was daar net een manier om 'n speellys te bou: kies elke liedjie een vir een. Toe kom Spotify met klaargemaakte speellyste — 'n onmiddellike versameling, geen moeite nie. 🎵\\n\\nETF's (Beursverhandelde Fondse) is die Spotify van belegging. In plaas daarvan om aandele een vir een te kies, koop jy EEN ETF wat 'n hele mandjie van hulle hou.\\n\\nDie meeste ETF's volg 'n INDEKS — 'n gepubliseerde lys maatskappye wat volgens 'n stel reëls saamgestel is. {etfDesc} Die ETF koop eenvoudig wat op die lys is, in dieselfde verhoudings, en werk homself by wanneer die lys verander.\\n\\nSo een {etf}-ETF gee jou 'n klein skyfie van {etfBasket} — name soos {top5} — in een enkele aankoop.\\n\\n⚠️ 'n Indeks is NIE outomaties 'die grootste maatskappye' nie. Sommige lyste rangskik volgens grootte, sommige volgens hoe swaar 'n aandeel verhandel word, en sommige word deur 'n komitee gekies. Twee indekse op dieselfde beurs kan heeltemal verskillende maatskappye hou. Lees altyd wat die lys werklik is voor jy dit koop.\\n\\nETF's is gewoonlik goedkoper, makliker en meer gediversifiseer as om self aandele te kies. Baie professionele fondsbestuurders kan hulle nie klop nie! 🤯","quiz":{"q":"Jy koop een {etf}-ETF. Wat besit jy nou?","options":["'n Klein skyfie van {etfBasket} — alles op een slag","Een aandeel in een groot maatskappy","Net die enkele grootste maatskappy op die {ex}"]}},"26":{"title":"{ex}-ETF's","desc":"Gewilde ETF's wat jy moet ken","content":"Daar is hope ETF's en indeksfondse wat jy vanuit {name} kan koop. Hier is 'n paar van die gewildstes:\\n\\n{etfList}\\n\\nDie reusagtige voordeel van ETF's: FOOIE. Baie aktief bestuurde fondse vra iets soos 1–2% per jaar, soms meer. Breë indeks-ETF's vra dikwels onder 0.2%. Op 'n belegging van {c}10,000 wat 20 jaar lank gehou word, is daardie gaping DUISENDE {cPlural} werd 💸\\n\\nGaan kyk na die fooi voor jy koop — dit word gewoonlik 'TER' of 'uitgaweverhouding' genoem. Niemand kan vir jou sê wat 'n ETF gaan opbring nie, maar die fooi is een syfer wat jy WEL vooraf kan weet.","quiz":{"q":"Jy wil in Apple, Alphabet en Amazon belê maar kan nie 'n aandeel van elk bekostig nie. Wat is die maklikste roete?","options":["Spaar jare lank tot jy elkeen kan koop","Jy moet elke maatskappy se aandeel afsonderlik koop","Koop 'n ETF wat die S&P 500 volg — al drie is reeds daarin"]}},"27":{"title":"Wêreldwye teenoor Plaaslike ETF's","desc":"Belê plaaslik en verder","content":"Moet jy net in maatskappye uit {name} belê? Kort antwoord: Nee! Hier is hoekom:\\n\\n🏠 PLAASLIKE ETF'S: Belê in {name} se maatskappye. Jy ken die handelsmerke, hulle is in {cPlural}. Maar as {name} se ekonomie sukkel, kan jou hele portefeulje val.\\n\\n🌍 WÊRELDWYE ETF'S: Belê in internasionale maatskappye — die VSA, Europa, Asië. {currencyHedge}\\n\\nValuta sny egter na altwee kante: as jou plaaslike geldeenheid STERKER word, is dieselfde buitelandse beleggings minder werd hier by die huis. Dit is die ruil wat jy aanvaar wanneer jy goed in die buiteland besit.\\n\\nOm albei plaaslik en wêreldwyd te hou, versprei jou oor twee verskillende risiko's tegelyk — jou eie ekonomie, en jou eie geldeenheid. Balans is alles! ⚖️","quiz":{"q":"{fxQuizSetup}. Wat gebeur met die {cName}-waarde van jou wêreldwye ETF?","options":["{fxQuizLose}","{fxQuizGain}","Dit bly dieselfde — geldeenheid raak nie ETF's nie"]}},"28":{"title":"Spaar teenoor Belê","desc":"Hoekom moet jou geld werk","content":"Albei is goed. Maar hulle dien verskillende doele:\\n\\n🏦 SPAAR: Sit geld in 'n bankrekening. Dit is veilig, jy kan enige tyd daarby uitkom. MAAR rentekoerse is gewoonlik {savings} — dikwels minder as inflasie. Jou geld is 'veilig' maar verloor stadig koopkrag.\\n\\n📈 BELÊ: Sit geld in aandele, ETF's of eiendom. Meer risiko, en geen waarborg in enige gegewe jaar nie — in sommige jare verloor jy eenvoudig geld. Oor lang tydperke het aandele egter histories meer opgelewer as kontant. {name} se mark het in die verlede gemiddeld ongeveer {mktReturn} per jaar opgelewer, en gemiddeldes uit die verlede is geskiedenis, nie 'n belofte nie.\\n\\nVuisreël:\\n• 3–6 maande se uitgawes in spaargeld (jou noodfonds) 🚨\\n• Geld wat jy vir jare nie sal nodig hê nie, is wat mense belê 🚀\\n\\nMoenie geld belê wat jy dalk volgende maand nodig het nie — dit is waarvoor spaargeld bedoel is!","quiz":{"q":"Jy het {c}5,000 in spaargeld. Jou maandelikse uitgawes is {c}800. Hoeveel behoort as noodfonds in spaargeld te bly?","options":["{c}2,400–{c}4,800 (3–6 maande se uitgawes), belê die res","Al {c}5,000 — spaar is altyd veiliger","{c}0 — belê alles vir maksimum groei"]}},"29":{"title":"Inflasie & Jou Geld","desc":"Hoekom verloor kontant waarde oor tyd","content":"Vra 'n grootmens wat 'n {food} gekos het toe hulle jou ouderdom was — iewers om en by {c}{foodOld}. Nou is dit {c}{foodNew}+. Dit is inflasie — pryse wat stadig oor tyd styg, wat beteken elke {cName} koop MINDER as vroeër.\\n\\n{name} se inflasie het gewoonlik om en by {inflation} per jaar geloop.\\n\\nSo as jou spaargeld 4% per jaar verdien maar inflasie 6% is, verloor jy eintlik sowat 2% koopkrag elke jaar — al het jou saldo opgegaan!\\n\\n💡 Jou beleggings moet inflasie klop om jou rykdom werklik te laat groei.\\n• Kontant onder die matras: verloor elke jaar waarde 💀\\n• Bankspaargeld: hou dikwels net-net by\\n• {ex}-aandele (langtermyngemiddeld): {mktReturn} per jaar — 'n gemiddelde uit die verlede, nie 'n belofte nie 🔥\\n\\nBelegging gaan nie net daaroor om ryk te word nie — dit gaan daaroor om nie armer te word nie! 💸","quiz":{"q":"Inflasie is vanjaar 6%. Jou spaarrekening verdien 4%. Wat gebeur met jou werklike koopkrag?","options":["Dit groei met 4%","Dit bly dieselfde — rente kanselleer inflasie uit","Dit krimp met sowat 2% — jy kan werklik minder koop"]}},"30":{"title":"Emosies & Belegging","desc":"Moenie in paniek verkoop of uit FOMO koop nie","content":"Die aandelemark is basies 'n toets van emosionele beheer. Die meeste mense druip dit. 🎭\\n\\n😱 PANIEKVERKOOP: Die mark val 20%, jy raak paniekerig, verkoop alles. Dan herstel dit. Jy het jou verlies vir niks vasgemaak nie.\\n\\n🤑 FOMO-KOOP: Almal op sosiale media hype 'n muntstuk. Jy storm in. Die prys stort dadelik ineen. Jy sit met die sak.\\n\\nDie beste beleggers hanteer 'n markineenstorting soos 'n uitverkoping by {retail} — hulle koop kalm aan in plaas van om paniekerig te raak. Warren Buffett het dit so gestel: 'Wees bang wanneer ander gulsig is, en gulsig wanneer ander bang is.'\\n\\nBou jou plan. Hou daarby. Jou toekomstige self sal jou bedank dat jy nie op 'n rooi dag woedend verkoop het nie! 🙏","quiz":{"q":"Die mark val 15% in een week. Almal in jou groepskletsie verkoop. Wat doen 'n slim langtermynbelegger gewoonlik?","options":["Verkoop alles dadelik om die verliese te stop","Bly kalm, hersien sy plan, en koop moontlik meer teen die laer prys","Kyk op sosiale media vir wenke oor wat om eerder te koop"]}},"31":{"title":"Die Finale Baas","desc":"Saamgestelde rente — die 8ste wonder van die wêreld","content":"'Die agtste wonder van die wêreld — hy wat dit verstaan, verdien dit; hy wat nie, betaal dit.' Jy sal daardie sin oral aanlyn aan Einstein toegeskryf sien. Daar is geen egte bewys dat hy dit gesê het nie.\\n\\nDie wiskunde is egter onweerlegbaar. Hier is die belangrikste ding wat jy ooit oor geld sal leer:\\n\\nIemand wat op 20 begin en {c}500/maand teen 12% per jaar belê, eindig op 65 met MEER as iemand wat op 35 begin en {c}2,000/maand teen dieselfde koers belê. Vier keer die maandelikse bedrag, en hulle eindig steeds agter.\\n\\nTyd. Is. Alles.\\n\\nDit is nie 'n truuk met die syfers nie, dit is juis die punt van saamgestelde groei: elke jaar wat jy wag, kos meer as wat enige jaar wat jy later bysit kan terugwen. Die beste oomblik om te begin was vroeër. Die tweede beste is nou.\\n\\nHierdie vasvra is jou finale toets. Slaan dit en jy is amptelik NoobTrader-gesertifiseer! 👑","bossVictory":"Saamgestelde rente ontsluit. Jy is nou gevaarlik. 🔥","quiz":{"q":"{c}1,000 wat teen 12% per jaar vir 10 jaar belê word, groei tot ~{c}3,106. Wat gebeur as jy die tyd VERDUBBEL na 20 jaar?","options":["Dit word meer as drie keer soveel, tot ~{c}9,646","Dit verdubbel ongeveer, tot ~{c}6,200","Die opbrengs vertraag hoe langer jy wag"]}},"32":{"title":"Kripto-platforms & Beursies","desc":"Waar kripto werklik woon","content":"Eers die eerlike deel: werklike kripto-platforms vereis in byna elke land dat jy 18+ is. Dit is hoekom NoobTrader jou toelaat om die hele ding eers met virtuele geld te oefen. 🎮\\n\\nWanneer grootmense kripto koop, gebruik hulle twee soorte plekke:\\n\\n🏦 BEURSE & MAKELAARSAPPS (bewaarnemend): jy maak 'n rekening, hulle hou jou kripto vir jou. Maklik, maar jy vertrou hulle. As hulle gekap word of bankrot speel, kan jou kripto verdwyn. Dit het al met van die grootste name in kripto gebeur.\\n\\n🔑 SELFBEWARINGSBEURSIES: 'n app waar JY die geheime sleutels hou. Niemand kan dit vries nie, maar niemand kan jou ook help nie. Verloor jou saadfrase (die 12 tot 24 geheime woorde) en die kripto is vir altyd weg. Geen wagwoordherstel nie. Geen kliëntediens nie. Weg.\\n\\nKriptomense sê: 'Nie jou sleutels nie, nie jou munte nie.' Nou weet jy wat dit beteken.","quiz":{"q":"Wat beteken dit wanneer 'n beurs jou kripto 'bewaarnemend' hou?","options":["Die kripto is gesluit en niemand kan dit ooit aanraak nie","Jy hou die geheime sleutels en net jy beheer dit","Die beurs hou die sleutels, so jy vertrou hulle daarmee","Dit verdien outomaties rente"]}},"33":{"title":"Hoe Kripto-aankope Werk","desc":"Spreidings, fooie en 24/7-markte","content":"Om kripto te koop lyk soos om enigiets aanlyn te koop, maar drie dinge is anders:\\n\\n1️⃣ DIE SPREIDING: die koopprys is altyd 'n bietjie hoër as die verkoopprys. Koop {c}100 se kripto en verkoop dit onmiddellik, en jy kry dalk {c}97 terug. Daardie gaping is hoe platforms stilweg verdien.\\n\\n2️⃣ FOOIE BO-OP: die meeste platforms vra ook 'n fooi per transaksie, dikwels 1 tot 2% vir klein aankope. Fooie plus spreiding beteken 'n klein aankoop begin sowat 3 tot 5% onder water voordat die prys enigsins beweeg.\\n\\n3️⃣ GEEN SLUITINGSKLOK NIE: aandelebeurse sluit snags en oor naweke. Kripto verhandel 24/7, elke dag van die jaar. Pryse kan ineenstort terwyl jy slaap. Dit is deel van hoekom kripto soveel meer wisselvallig is as aandele.\\n\\nIn NoobTrader kan jy kripto met virtuele geld verhandel en hierdie kragte sien uitspeel sonder om 'n sent te verloor. 📊","quiz":{"q":"Jy koop {c}100 se munt en verkoop dit 5 sekondes later. Hoekom kry jy minder as {c}100 terug?","options":["Die spreiding en fooie vat 'n snit in elke rigting","Kriptopryse val altyd nadat jy gekoop het","Die platform hef belasting","Jy kan eers ná 24 uur verkoop"]}},"34":{"title":"Gasfooie Verduidelik","desc":"Hoekom kos dit geld om kripto te stuur","content":"Om kripto te stuur is nie gratis nie. Elke transaksie betaal 'n netwerkfooi, dikwels GAS genoem, aan die rekenaars wat die netwerk verwerk en beveilig.\\n\\nHier is die deel wat almal verras: gas word deur netwerkverkeer bepaal, NIE deur hoeveel jy stuur nie. Wanneer die netwerk besig is, skiet fooie op.\\n\\n🤯 Op sommige netwerke kan dit, op besige tye, MEER as {c}10 in gas kos om {c}10 se kripto te stuur. Jy sou meer vir die aflewering betaal as wat die pakkie werd is.\\n\\nNuwer netwerke en 'laag 2'-stelsels bestaan grootliks om dit goedkoper te maak, met fooie van 'n paar sent. Enigiemand wat met kripto werk, kyk na die fooi VOORDAT hulle stuur druk.\\n\\nNog een ding: kripto-oordragte kan nie omgekeer word nie. Verkeerde adres plus betaalde gas is gelyk aan geld wat permanent weg is. Daar is geen bank om te bel nie. ☎️❌","quiz":{"q":"Gasfooie is vandag hoog. Jy wil {c}15 se kripto stuur en gas kos {c}20. Wat is die slim lesing?","options":["Stuur dit, fooie kom later terug","Stuur die helfte, dan halveer die fooi","Gas geld net vir groot oordragte, so dit is gratis onder {c}50","Moenie dit stuur nie, want die fooi kos meer as wat die oordrag werd is"]}},"35":{"title":"Meme-munte & Rug Pulls","desc":"Sien die strikke voor hulle jou sien","content":"Meme-munte is kriptos wat op grappe en hype gebou is in plaas van enige werklike nut. 'n Paar het vroeë kopers ryk gemaak, en dit is presies hoekom daar duisende namaaksels bestaan. Byna almal van hulle gaan na nul. 📉\\n\\nDie gemeenste strik is die RUG PULL: die skeppers maak 'n munt, hype dit hard, wag dat mense instroom, en dump dan hulle enorme voorraad of dreineer die verhandelingspoel. Die prys stort binne minute in. Hulle hou die geld. Jy hou die waardelose munte.\\n\\n🚩 ROOI VLAE om te memoriseer:\\n• 'n Anonieme span wat jy nie kan verifieer nie\\n• 'Gewaarborgde' opbrengste (niks in markte is gewaarborg nie)\\n• Beïnvloeders wat betaal word om dit aan te prys\\n• 'n Piepklein groepie hou die meeste van die aanbod\\n• Druk om 'te koop voordat dit te laat is'\\n\\nAs 'n munt se hoofargument is dat ANDER mense wat dit koop JOU ryk gaan maak, is dit nie belegging nie. Dit is 'n speletjie van musiekstoele, en die skeppers besit die musiek. 🎵","quiz":{"q":"'n Splinternuwe munt het 'n anonieme span, belowe 'gewaarborgde 100x' en betaalde beïnvloeders stoot dit hard. Wat word hierdie patroon genoem?","options":["'n Blou-skyf-belegging","Die klassieke opstelling vir 'n rug pull","Kostemiddeling","'n Stabielmunt"]}},"36":{"title":"Myn teenoor Verhandel teenoor Staking","desc":"Drie baie verskillende speletjies","content":"Drie maniere waarop mense in kripto probeer verdien, en dit is NIE dieselfde speletjie nie:\\n\\n⛏️ MYN: kragtige rekenaars wedywer om transaksies te verwerk en nuwe munte te verdien. Klink lekker, maar Bitcoin-myn is vandag industrieel: pakhuise vol gespesialiseerde masjiene en enorme elektrisiteitsrekeninge. Jou foon of skootrekenaar kan nie meeding nie, en 'myn Bitcoin op jou foon!'-apps is byna altyd bedrogspul of advertensieplase wat jou omtrent niks betaal nie.\\n\\n🥩 STAKING: op sommige netwerke sluit jy munte toe om die netwerk te help beveilig en beloninge te verdien, 'n bietjie soos rente. Dit is eg, maar jou munte kan 'n ruk lank gesluit wees, en hulle PRYS kan steeds ineenstort terwyl hulle gesluit is.\\n\\n📊 VERHANDEL: koop en verkoop om uit prysbewegings wins te maak. Geen hardeware nodig nie, maar dit is die speletjie waar dissipline die meeste saak maak, en waar die meeste beginners teen hulle eie emosies verloor.\\n\\nNoobTrader leer die verhandelingspeletjie met geen risiko nie. Die ander twee het regte geld nodig om selfs te begin.","quiz":{"q":"'n App sê jou foon kan winsgewend Bitcoin myn terwyl jy slaap. Wat is die mees waarskynlike waarheid?","options":["Fone myn stadig maar winsgewend as hulle aan die laai bly","Dit is eg maar werk net op die nuutste fone","Dit is byna seker 'n bedrogspul of betaal omtrent niks nie, want fone kan nie met industriële myners meeding nie","Myn is onwettig op fone"]}},"37":{"title":"Kripto-sekuriteit & Bedrogspul","desc":"Hou wat joune is, joune","content":"Kripto se superkrag is ook sy gevaar: transaksies kan nie omgekeer word nie en daar is geen bank om 'n fout ongedaan te maak nie. Bedrieërs is mal daaroor. Hier is jou verdedigingstel:\\n\\n🔐 JOU SAADFRASE IS HEILIG. Niemand wettig sal dit OOIT vra nie. Nie 'ondersteuningspersoneel' nie, nie 'n 'verifikasiebot' nie, niemand nie. Enigiemand wat jou saadfrase vra, steel van jou, punt.\\n\\n🎣 PHISHING: vals webwerwe en DM's wat presies soos die regte platforms lyk. Een letter verkeerd in die webadres. Tik die adres altyd self in.\\n\\n🎁 WEGGEE-BEDROG: 'Stuur 1 munt, kry 2 terug!', dikwels met 'n bekende se gekapte rekening. Niemand verdubbel jou geld nie. Nooit.\\n\\n💕 ROMANSE- & 'BELEGGINGSMENTOR'-BEDROG: 'n vriendelike vreemdeling wat jou stadig na 'n 'spesiale platform' toe praat. Die platform is vals. Die onttrekkings werk nooit.\\n\\nDie patroon onder elke bedrogspul: dringendheid plus geheimhouding plus gewaarborgde wins. Sien jy daardie drie saam, stap weg. 🚶","quiz":{"q":"Iemand wat beweer hulle is 'platformondersteuning' stuur jou 'n DM en vra jou 12-woord-saadfrase om 'jou beursie te verifieer'. Wat doen jy?","options":["Deel dit nooit nie, want werklike ondersteuning vra nooit 'n saadfrase nie","Deel dit, want ondersteuningspersoneel is geverifieer","Deel net die eerste 6 woorde om veilig te wees","Vra hulle om jou eers te e-pos, en deel dit dan"]}},"38":{"title":"Die Kripto-baas","desc":"Die Bitcoin-tydmasjien","content":"Tyd vir die storie wat almal aanhaal en niemand behoorlik vertel nie.\\n\\nVroeg in 2017 het een Bitcoin omtrent $1,000 gekos. In Desember 2024 het dit vir die eerste keer $100,000 verbygesteek. 'n Aankoop van $1,000, wat die hele pad gehou is, het omtrent $100,000 geword. Dit is 'n 100x. 🤯\\n\\nNou die deel wat die hype uitlaat: om daardie 100x te kry, moes jy deur twee brutale ineenstortings sit, een van sowat 84% en nog een van sowat 77%, en JARE lank kyk hoe jou geld krimp sonder om te verkoop. Byna niemand het dit reggekry nie. Die meeste mense het hoog gekoop, in die ineenstorting gepaniek, en laag verkoop.\\n\\nEn vir elke Bitcoin is daar duisende dooie munte wat na nul gegaan het. Om die wenner vooraf te kies, lyk net agterna maklik. Dit word oorlewingsydigheid genoem, en dit is die duurste illusie in kripto.\\n\\nDie werklike les van die tydmasjien: vir die munte wat oorleef het, het geduld tydsberekening geklop. Maar jy vind eers AGTERNA uit watter munte oorleef, en dit is hoekom diversifikasie heldekeuses klop, en hoekom NIEMAND die toekoms ken nie. Selfs nie die baas nie. 🐉","bossVictory":"Kripto-module verower. Jy weet nou meer as die meeste grootmense. 🐉","quiz":{"q":"Duisende munte is saam met Bitcoin gelanseer, en die meeste is nou omtrent niks werd nie. Hoekom lyk \\"kies net die volgende Bitcoin\\" so maklik wanneer jy terugkyk?","options":["Omdat die wenners die enigstes is waaroor mense nog praat — dié wat gesterf het, het uit die storie verdwyn","Omdat die beste munte van die begin af voor die hand liggend is as jy genoeg lees","Omdat die meeste munte uiteindelik regkom as jy lank genoeg hou","Omdat kenners Bitcoin reeds in 2010 korrek voorspel het"]}},"39":{"title":"Wat IS 'n Blockchain Eintlik?","desc":"Die tegnologie onder dit alles","content":"Haal die hype weg en 'n blockchain is verbasend eenvoudig: 'n gedeelde rekordboek waarvan duisende rekenaars identiese kopieë hou.\\n\\nWanneer iemand kripto stuur, gaan daardie transaksie saam met honderde ander in 'n 'blok' in. Die blok word met wiskunde verseël en aan die vorige blok geketting. Vandaar: blok. Ketting. ⛓️\\n\\nHoekom gee enigiemand om? Weens wat dit moontlik maak:\\n\\n✅ Niemand kan stilletjies die geskiedenis verander nie. Om 'n ou blok te verander sou beteken om elke blok daarna op duisende rekenaars gelyktydig oor te doen.\\n✅ Geen enkele maatskappy of regering bestuur dit nie. Die netwerk van rekenaars bestuur dit saam.\\n✅ Enigiemand kan die rekord nagaan. Elke Bitcoin-transaksie wat ooit gemaak is, is openbaar sigbaar.\\n\\nDit is werklik nuwe tegnologie. Dit is ook NIE towergeld nie. 'n Perfekte rekord van 'n waardelose munt is steeds 'n waardelose munt. Dat die tegnologie eg is, maak nie elke munt wat daarop gebou is waardevol nie. 🧠","quiz":{"q":"Hoekom is dit so moeilik om 'n ou transaksie op 'n blockchain in die geheim te verander?","options":["Omdat die regering elke verandering goedkeur","Omdat jy elke latere blok op duisende rekenaars gelyktydig sou moes oordoen","Omdat transaksies ná 'n maand uitgevee word","Omdat net die munt se skepper die rekord kan wysig"]}},"40":{"title":"Bitcoin teenoor Al die Res","desc":"Nie alle munte is dieselfde speletjie nie","content":"'Kripto' is nie een ding nie. Die verskille maak meer saak as die ooreenkomste:\\n\\n₿ BITCOIN: die oorspronklike. Sy aanbod is vir altyd op 21 miljoen munte beperk, in die kode geskryf, en die tempo van nuwe munte halveer ongeveer elke vier jaar. (Klink bekend? NOOB se halvering leen presies hierdie idee.) Sy hele argument is skaarsheid plus sekuriteit.\\n\\n⟠ ETHEREUM: minder 'digitale goud', meer 'wêreldrekenaar'. Dit loop slim kontrakte, wat programme is wat outomaties uitvoer. Die meeste kripto-apps is daarop of op sy mededingers gebou.\\n\\n🪙 AL DIE RES: duisende 'altmunte'. 'n Paar los werklike probleme op. Die meeste is kopieë, eksperimente, of geldgrype. Die brutale statistiek: die meerderheid munte wat ooit geskep is, is reeds dood of waardeloos.\\n\\nLes: 'kripto gaan op' vertel jou omtrent niks oor enige SPESIFIEKE munt nie. Elkeen is sy eie weddenskap, met sy eie kanse. 🎲","quiz":{"q":"Wat is Bitcoin se maksimum aanbod, en kan dit maklik verander word?","options":["100 miljoen, en myners stem jaarliks daaroor","Daar is geen maksimum nie, nuwe munte druk vir altyd","1 miljard, soos NOOB","21 miljoen, vas in die kode, en prakties onmoontlik om te verander"]}},"41":{"title":"Stabielmunte","desc":"Kripto wat probeer stilstaan","content":"'n Stabielmunt is 'n kripto wat ontwerp is om altyd 'n vaste bedrag werd te wees, gewoonlik presies 1 Amerikaanse dollar. Handelaars gebruik hulle as 'n parkeerplek: verkoop jou wisselvallige munte in 'n stabielmunt in, en jou geld staan stil terwyl jy oor die volgende skuif besluit.\\n\\nHoe bly hulle op $1? Die hoofontwerp hou werklike dollars en bates in reserwe, sodat elke munt deur iets gerugsteun word. Jy vertrou wie ook al daardie reserwes hou.\\n\\nEn hier is jou waarskuwingsverhaal: stabielmunte kan BREEK. Dit het werklik gebeur. In 2022 het 'n groot 'algoritmiese' stabielmunt, wat slim wiskunde in plaas van werklike reserwes gebruik het, binne dae van $1 tot byna nul ineengestort en tienemiljarde dollars laat verdamp. 'Stabiel' is 'n ontwerpdoel, nie 'n waarborg nie.\\n\\nVuisreël: hoe slimmer die meganisme wat iets 'veilig' hou, hoe harder moet jy daarna kyk. 🔍","quiz":{"q":"Wat is 'n stabielmunt se hooftaak?","options":["Om 'n vaste waarde te hou, gewoonlik $1, sodat handelaars 'n stabiele parkeerplek het","Om vinniger as Bitcoin te groei","Om outomaties rente te betaal","Om transaksies vir almal weg te steek"]}},"42":{"title":"Kripto, Belasting & die Wet","desc":"Ja, die reëls geld","content":"Die internet is vol mense wat glo kripto is onsigbare geld sonder reëls. Hulle kom dit gewoonlik op die harde manier agter. 😬\\n\\nDie werklikheid in die meeste lande, Suid-Afrika ingesluit:\\n\\n🧾 WINSTE IS GEWOONLIK BELASBAAR. Verkoop kripto vir meer as wat jy betaal het, en die belastinggesag wil oor die algemeen sy deel hê, net soos met aandele.\\n\\n🪪 BEURSE WEET WIE JY IS. Wettige platforms vereis ID-verifikasie (genoem KYC, Know Your Customer). Elke transaksie word ook permanent op die blockchain self aangeteken, wat die TEENOORGESTELDE van anoniem is.\\n\\n⚖️ REGULEERDERS IS BETROKKE. In Suid-Afrika word kripto-bates amptelik as finansiële produkte hanteer, wat beteken die platforms wat hulle verkoop moet die finansiëledienste-reëls volg.\\n\\nNiks hiervan is 'n rede om te paniek nie. Dit IS 'n rede om enigiemand te ignoreer wat sê 'die reëls geld nie vir kripto nie'. Hulle geld wel, en om anders voor te gee, laat grootmense in werklik ernstige moeilikheid beland.","quiz":{"q":"Jou neef sê kripto-winste is onsigbaar vir die belastinggesag omdat kripto anoniem is. Wat is fout daarmee?","options":["Niks, kripto is heeltemal anoniem","Kripto-winste word net in Amerika belas","Beurse verifieer identiteite en blockchains teken alles permanent aan, en winste is oor die algemeen belasbaar","Belasting geld net as jy meer as 'n miljoen onttrek"]}},"43":{"title":"Wisselvalligheid & Oorlewingsreëls","desc":"Hoekom swaai kripto so hard","content":"'n Slegte dag op die aandelemark is 3%. 'n Slegte dag in kripto is 20%. Selfs Bitcoin, die 'grootmens' van kripto, het meer as een keer meer as 80% van sy waarde verloor en later herstel. Kleiner munte verloor gereeld 95% en kom nooit terug nie.\\n\\nHoekom so wild? Kripto verhandel 24/7 sonder stroombrekers, baie daarvan word met geleende geld gekoop wat in ineenstortings gedwing word om te verkoop, en pryse loop op stories en emosie eerder as op verdienstverslae.\\n\\nSo, die oorlewingsreëls, wat elke ervare handelaar herhaal:\\n\\n1️⃣ Sit nooit geld in wat jy nie heeltemal kan bekostig om te verloor nie.\\n2️⃣ Hou posisies klein genoeg dat een ramp jou nie kan uitvee nie.\\n3️⃣ Besluit jou uitgang VOOR jy ingaan, terwyl jy kalm is.\\n4️⃣ FOMO is die duurste gevoel in finansies.\\n\\nOefen al vier in NoobTrader waar die verliese kastig is. Die gewoontes is die werklike prys. 🏆","quiz":{"q":"Watter een van hierdie is 'n werklike oorlewingsreël vir wisselvallige markte?","options":["Verdubbel jou posisie ná elke verlies om dit terug te wen","Belê nooit geld wat jy nie heeltemal kan bekostig om te verloor nie","Wisselvalligheid raak net klein munte, so groot munte is veilig","Koop altyd wanneer almal op sosiale media koop"]}},"44":{"title":"Hype-siklusse & FOMO","desc":"Die patroon agter elke manie","content":"Kripto loop in hype-siklusse, en sodra jy die patroon kan sien, kan jy dit nooit weer ontsien nie:\\n\\n📈 Fase 1: iets werkliks gebeur. Vroeë gelowiges koop stilweg.\\n🚀 Fase 2: pryse styg. Die media merk dit op. Jou voer vul met wenners.\\n🎪 Fase 3: manie. Taxibestuurders gee muntwenke. Mense leen om te koop. 'Hierdie keer is anders.'\\n💥 Fase 4: die ineenstorting. Laatkommers, wat die hoogste gekoop het, verloor die meeste.\\n🕳️ Fase 5: stilte. Die wenners se plasings verdwyn. Niemand praat oor hulle verliese nie.\\n\\nDie NFT-oplewing van 2021 het presies hierdie draaiboek gevolg: digitale versamelstukke wat aan die bopunt vir miljoene verkoop is, en 'n paar jaar later was die meeste omtrent niks werd nie.\\n\\nDie wrede truuk van elke manie: dit laat die SLEGSTE tyd om te koop soos die MEES DRINGENDE tyd om te koop voel. Wanneer dit die veiligste voel om in te storm, juis omdat almal anders reeds daar is, is die maklike winste gewoonlik weg. 🎯","quiz":{"q":"Wanneer voel die gemiddelde persoon in 'n klassieke hype-siklus die sterkste drang om te koop?","options":["Fase 1, wanneer niemand daaroor praat nie","Tydens die ineenstorting, wanneer pryse die laagste is","Dit is lukraak en volg geen patroon nie","Naby die top, wanneer almal om hulle reeds in is en dit die veiligste voel"]}},"45":{"title":"Lees 'n Kers","desc":"Kersanatomie: liggaam en kleur","content":"Elke kers vertel 'n klein storie met net vier syfers: waar die prys oopgemaak het, die hoogste wat dit bereik het, die laagste waarheen dit geval het, en waar dit gesluit het. Die soliede liggaam loop van oop tot sluit, en die kleur vertel jou wie gewen het: groen beteken die sluiting het bo die opening geëindig, rooi beteken die verkopers het dit daaronder gesleep. Dit is die hele truuk. Leer om een kers behoorlik te lees, en elke grafiek ter wêreld verander van 'n muur van geraas in 'n strokiesprent. 🟢","quiz":{"q":"Hierdie kers is groen. Wat vertel dit jou van daardie verhandelingstydperk?","options":["Die prys het laer gesluit as wat dit oopgemaak het","Meer mense het gekoop as wat verkoop het, gewaarborg","Die prys het hoër gesluit as wat dit oopgemaak het","Die prys het glad nie tydens die tydperk gedaal nie"]}},"46":{"title":"Wieke Vertel Stories","desc":"Kersanatomie: hoogte- en laagtepunte","content":"Die liggaam wys waar die tydperk oopgemaak en gesluit het, maar die wieke wys die volle reis: elke prys wat die geveg werklik bereik het. 'n Lang wiek beteken 'n groot geveg het buite die opening en sluiting plaasgevind, en die kant wat die wiek agtergelaat het, het daardie geveg verloor. Lang wiek onder? Verkopers het hard gestoot en is teruggeslaan. Lang wiek bo? Kopers het hoog gereik en is verwerp. Die liggaam is die opskrif, die wieke is die skinderstories. 📏","quiz":{"q":"Wat wys die dun lyne (die wieke) bo en onder die liggaam eintlik?","options":["Die hoogste en laagste pryse wat tydens die tydperk verhandel is","Gister se opening en sluiting","Die presiese pryse waar die meeste transaksies plaasgevind het","'n Voorspelling van môre se reeks"]}},"47":{"title":"Die Doji","desc":"Enkelkerse: besluiteloosheid","content":"Soms maak 'n kers oop en sluit teen byna presies dieselfde prys, en laat 'n piepklein liggaam met wieke aan albei kante. Dit is 'n doji, en dit beteken die toutrek het op 'n dooie gelykop geëindig: kopers en verkopers het die hele sessie hard getrek en nie een kant het gewen nie. Op sy eie is dit net 'n skouerophaling. Ná 'n sterk opmars kan dit aandui dat die neiging moeg word, want die kant wat besig was om te wen, kon skielik nie die prys beweeg nie. 'n Leidraad wat die moeite werd is om raak te sien, nooit 'n waarborg nie. 🤝","quiz":{"q":"Die gloeiende kers het teen byna presies dieselfde prys oopgemaak en gesluit. Wat word dit genoem, en wat dui dit aan?","options":["'n Marubozu, 'n teken van algehele oortuiging","'n Hamer, 'n teken dat kopers beheer geneem het","'n Gaping, 'n teken dat verhandeling gestop het","'n Doji, 'n teken van besluiteloosheid tussen kopers en verkopers"]}},"48":{"title":"Die Hamer","desc":"Enkelkerse: die terugveg","content":"Stel jou 'n brutale sessie voor: verkopers slaan die prys af, dan sleep kopers dit al die pad terug voor die sluiting. Wat op die grafiek oorbly is 'n hamer: 'n klein liggaam naby die bokant met 'n lang onderste wiek wat minstens twee keer so groot is. Ná 'n glyplek af sê 'n hamer die verkopers het hulle beste hou probeer en dit het nie geland nie. Dit merk dikwels 'n moontlike draai. Moontlik, nie belowe nie, so hanteer dit as 'n leidraad om dop te hou, nie 'n opdrag om te koop nie. 🔨","quiz":{"q":"Ná 'n glyplek af het die gloeiende kers 'n lang onderste wiek en 'n klein liggaam naby die bokant gedruk. Wat is dit?","options":["'n Vallende ster, 'n teken dat verkopers oorgeneem het","'n Hamer, 'n aanduiding dat kopers hard teruggeveg het","'n Doji, 'n perfekte gelykop","Bewys dat die afwaartse neiging klaar is"]}},"49":{"title":"Die Vallende Ster","desc":"Enkelkerse: verwerping by die top","content":"Die spieëlbeeld van die hamer. Ná 'n sterk klim reik kopers na nog een nuwe hoogtepunt, word hard verwerp, en die prys sluit weer af naby waar dit oopgemaak het. Die grafiek druk 'n klein liggaam aan die onderkant van die kers met 'n lang boonste wiek: 'n vallende ster. Dit beteken die verkopers het uiteindelik by die top opgedaag met genoeg krag om die sessie te wen. Ná 'n groot opmars maak daardie verwerping dikwels saak. Dikwels, nie altyd nie. 🌠","quiz":{"q":"Ná 'n sterk klim het die gloeiende kers opgeskiet en toe naby sy laagtepunt gesluit, met 'n lang boonste wiek. Wat is dit?","options":["'n Vallende ster, 'n aanduiding dat verkopers by die top opgedaag het","'n Hamer, 'n aanduiding dat kopers weer in beheer is","'n Groen marubozu, suiwer koopkrag","'n Waarborg dat die prys môre ineenstort"]}},"50":{"title":"Die Marubozu","desc":"Enkelkerse: algehele oortuiging","content":"'n Marubozu is een soliede liggaam met geen wieke nie: die prys het oopgemaak en die hele sessie in een rigting gemarsjeer sonder om ooit terug te kyk. Geen geveg nie, geen huiwering nie, algehele oortuiging van een kant af. 'n Groen marubozu skreeu koperselfvertroue, 'n rooi een skreeu die teenoorgestelde. Hulle is skaars, en dit is juis hoekom handelaars regop sit wanneer een verskyn. 💪","quiz":{"q":"Die gloeiende kers is een soliede liggaam met geen wieke nie. Wat vertel daardie vorm jou?","options":["Niemand het tydens daardie tydperk verhandel nie","Die mark het daardie dag vroeg gesluit","Een kant was van oop tot sluit in beheer, algehele oortuiging","Kopers en verkopers was perfek gebalanseerd"]}},"51":{"title":"Die Bullish Engulfing","desc":"Tweekers-patrone: kopers slaan toe","content":"Twee kerse, een boodskap. Eers 'n klein rooi kers, doodgewone sake vir 'n afwaartse neiging. Dan 'n groot groen liggaam wat dit heeltemal insluk: in een sessie het kopers alles uitgevee wat die verkopers die vorige dag reggekry het, en nog meer. Wanneer dit ná 'n afwaartse neiging land, is die bullish engulfing een van die mees dopgehoude omkeer-leidrade op enige grafiek, want dit wys hoe die magsbalans in 'n enkele kers omslaan. 'n Leidraad, nie 'n kontrak nie. 🐂","quiz":{"q":"Die groot groen liggaam sluk die rooi liggaam voor hom heeltemal in. Wat is hierdie tweekers-patroon?","options":["'n Bearish engulfing, verkopers het beheer geneem","'n Bullish engulfing, kopers het die verkopers oorweldig","'n Dubbelbodem","Twee dojis agtermekaar"]}},"52":{"title":"Die Bearish Engulfing","desc":"Tweekers-patrone: verkopers slaan toe","content":"Die spieëlbeeld van die bullish weergawe. Aan die bopunt van 'n klim sluk 'n groot rooi liggaam die hele groen liggaam voor hom in: verkopers het die vorige dag se kopery in een kers uitgewis, presies waar die klim reeds uitgerek was en die nuutste kopers senuweeagtig was. Dit maak gewoonlik die res van die kopers ook senuweeagtig. Wanneer jy dit ná 'n lang opmars sien, respekteer dit. 🐻","quiz":{"q":"Aan die bopunt van 'n klim sluk die groot rooi liggaam die hele groen liggaam voor hom in. Wat word hierdie paar genoem?","options":["'n Bullish engulfing, die klim gaan voort","'n Hamer gevolg deur 'n doji","'n Uitbraak bo weerstand","'n Bearish engulfing, verkopers het die kopers oorweldig"]}},"53":{"title":"Herken 'n Opwaartse Neiging","desc":"Neigings: hoër hoogtepunte, hoër laagtepunte","content":"'n Opwaartse neiging het albei helftes nodig: hoër hoogtepunte ÉN hoër laagtepunte. Elke piek klop die vorige een, en elke duik stop hoër as die een voor hom, want kopers stap elke keer vroeër in. Daardie trapvorm is die mark wat vir jou sê vraag is in beheer. Een hoër hoogtepunt op sy eie bewys niks. Die patroon is die paar, wat herhaal. 📈","quiz":{"q":"Elke piek klop die vorige een, en elke duik stop hoër as die een voor hom. Wat wys hierdie grafiek?","options":["'n Opwaartse neiging, hoër hoogtepunte en hoër laagtepunte","'n Afwaartse neiging, laer hoogtepunte en laer laagtepunte","'n Reeks, die prys sit vas tussen 'n vloer en 'n plafon","'n Dubbeltop wat besig is om te vorm"]}},"54":{"title":"Herken 'n Afwaartse Neiging","desc":"Neigings: laer hoogtepunte, laer laagtepunte","content":"Draai die trap onderstebo. Laer hoogtepunte beteken verkopers val vroeër aan by elke opbons, laer laagtepunte beteken kopers wyk verder terug by elke val. Solank daardie struktuur hou, is die verkopers in beheer, en om daarteen te veg is hoe nuwe handelaars geld aan geduldiges skenk. Die neiging is nie jou vyand nie, maar om voor te gee dat dit nie daar is nie, is beslis. 📉","quiz":{"q":"Elke opbons eindig laer as die vorige, en elke val sny dieper. Waarna kyk jy?","options":["'n Opwaartse neiging wat asem skep","'n Sywaartse reeks","'n Afwaartse neiging, laer hoogtepunte en laer laagtepunte","'n Bullish engulfing-patroon"]}},"55":{"title":"Die Sywaartse Mark","desc":"Neigings: die wagspeletjie","content":"Soms wen nie een kant nie, so die prys pingpong net weke lank tussen dieselfde vloer en dieselfde plafon. Dit is 'n reeks, en markte spandeer 'n reuse deel van hulle lewe presies hieraan. Dit is nie stukkend nie en dit is nie vervelig nie, dit is die mark wat asem skep. Geduldige handelaars leer om die wag lief te hê, want hoe langer 'n reeks hou, hoe betekenisvoller is die uiteindelike ontsnapping gewoonlik. 🏓","quiz":{"q":"Die prys bons al weke lank tussen dieselfde vloer en dieselfde plafon. Wat word dit genoem?","options":["'n Opwaartse neiging, dit raak die plafon oor en oor","'n Reeks, die mark beweeg sywaarts","'n Kop en skouers","'n Uitbraak wat besig is om te gebeur"]}},"56":{"title":"Steun","desc":"Steun & weerstand: die vloer","content":"Wanneer die prys aanhou val tot by dieselfde vlak en elke enkele keer terugbons, noem handelaars daardie vlak steun: 'n vloer waar kopers aanhou besluit die prys is 'n winskoop. Hoe meer kere dit hou, hoe meer mense hou dit dop, wat deels is hoekom dit aanhou hou. Maar onthou die vloer word deur mense geteken, nie deur die wet nie. Steun kan breek en breek wel, en wanneer dit breek, word die bons-skare die paniek-skare. 🧱","quiz":{"q":"Die prys het drie keer tot in die skaduvlak geval, en elke enkele keer teruggebons. Wat noem handelaars daardie vlak?","options":["Weerstand, 'n plafon waar verkopers instroom","'n Neigingslyn, vlakke moet skuins wees","'n Stop-verlies wat deur die beurs gestel is","Steun, 'n vloer waar kopers aanhou instap"]}},"57":{"title":"Weerstand","desc":"Steun & weerstand: die plafon","content":"Weerstand is die plafon: 'n vlak waar elke opmars aanhou stol omdat verkopers gelukkig is om daar hulle wins te vat. Kyk hoe 'n grafiek drie keer sy kop teen dieselfde prys stamp en jy sien weerstand in reële tyd werk. Hier is die draai wat die moeite werd is om te onthou: as die prys ooit met werklike oortuiging deurbreek, begin daardie ou plafon dikwels soos 'n nuwe vloer optree. 🪟","quiz":{"q":"Drie afsonderlike opmarse het by die skaduvlak gestol. Wat word daardie vlak genoem?","options":["Weerstand, 'n plafon waar verkopers aanhou terugstoot","Steun, 'n vloer onder die prys","Die dividendvlak","'n Volumepiek"]}},"58":{"title":"Neigingslyne","desc":"Neigingslyne & kanale: die lyn wat saak maak","content":"Verbind die stygende laagtepunte op 'n grafiek en jy het 'n neigingslyn geteken. Enige twee punte maak 'n lyn, maar die derde raakpunt is waar dit begin bewys dat dit saak maak, want dit wys kopers verdedig aanhoudend dieselfde stygende vlak. Elke ekstra gerespekteerde raakpunt is meer bewys. Dit bly bewys, nooit 'n belofte nie: 'n neigingslyn is 'n potloodmerk, nie 'n kragveld nie. ✏️","quiz":{"q":"Hierdie stygende lyn is drie afsonderlike kere geraak. Hoekom gee handelaars om hoeveel raakpunte 'n neigingslyn het?","options":["Hulle gee nie om nie, enige twee punte maak 'n neigingslyn 'n reël","Drie raakpunte beteken 'n vierde bons is gewaarborg","Meer raakpunte maak die lyn betekenisvoller, kopers verdedig dit aanhoudend","Neigingslyne tel net op daaglikse grafieke"]}},"59":{"title":"Kanale","desc":"Neigingslyne & kanale: die baan","content":"'n Kanaal is 'n neiging met maniere. Die prys klim terwyl dit tussen twee parallelle lyne bons: 'n vloer van stygende laagtepunte en 'n plafon van stygende hoogtepunte, wat saam opbeweeg soos die kante van 'n baan. Handelaars hou albei rande dop vir bonse, en hulle hou nog harder dop vir die dag wat die prys die baan verlaat, want 'n skoon uitbreek uit 'n kanaal is dikwels waar die volgende groot beweging begin. 🛣️","quiz":{"q":"Die prys klim terwyl dit tussen twee parallelle lyne bons. Wat is hierdie patroon?","options":["'n Driehoek, die lyne moet ontmoet","'n Stygende kanaal, 'n opwaartse neiging met 'n sigbare baan","'n Dubbeltop","'n Plat reeks"]}},"60":{"title":"Die Dubbeltop","desc":"Grafiekpatrone: die M-vorm","content":"Die prys stamp twee keer teen dieselfde plafon, misluk albei kere, en teken 'n groot M op die grafiek. Breek onder die duik in die middel (die neklyn) en die dubbeltop is voltooi: 'n klassieke bearish omkeer-leidraad. Sy spieëlbeeld, die W, is die dubbelbodem, en dit wys die ander kant toe. Dit merk gewoonlik 'n top, maar hoef nie. Niks op 'n grafiek hoef nie. Ⓜ️","quiz":{"q":"Die prys het twee keer teen dieselfde plafon gestamp, albei kere misluk, en toe onder die duik in die middel gebreek. Wat is hierdie vorm?","options":["'n Dubbelbodem, 'n bullish leidraad","'n Stygende kanaal","'n Hamer","'n Dubbeltop, 'n bearish omkeer-leidraad"]}},"61":{"title":"Wanneer Patrone Misluk","desc":"Grafiekpatrone: waarskynlikhede, nie beloftes nie","content":"Dit is die waardevolste les in die module. 'n Handboekpatroon het gevorm, almal het dit gesien, en toe doen die mark die teenoorgestelde. Elke patroon wat jy geleer het, misluk soms, en dit is nie die grafiek wat vir jou lieg nie, dit is die grafiek wat vir jou inligting gee: die kant wat jy gesteun het, het pas verloor. Besluit jou uitgang voor jy ingaan, en wanneer 'n patroon misluk, vat die wenk en klim uit. Patrone is waarskynlikhede, nooit beloftes nie. 🚪","quiz":{"q":"'n Handboek-dubbelbodem het by die skaduvloer gevorm... toe val die prys reguit daardeur. Wat is die eerlike les?","options":["Patrone is waarskynlikhede, nie beloftes nie, en 'n mislukte patroon is jou wenk om uit te klim","Werklike dubbelbodems misluk nooit nie, so hierdie een was vals","Koop meer, die patroon sal uiteindelik nog steeds uitspeel","Grafieke hou op werk sodra 'n patroon misluk"]}},"62":{"title":"Kop & Skouers","desc":"Grafiekpatrone: drie pieke","content":"Drie pieke: 'n hoër een in die middel (die kop), 'n laer een aan elke kant (die skouers), en 'n lyn onder die twee duike wat die neklyn genoem word. Dit vorm wanneer kopers een laaste, hoër stoot regkry en dit dan by die volgende poging nie eens kan ewenaar nie. Die vorm alleen is net 'n waarskuwing. Waarvoor handelaars werklik wag, is 'n beslissende breek onder die neklyn, want dit is wanneer die patroon ophou om 'n tekening te wees en 'n besluit word. 👤","quiz":{"q":"Drie pieke: 'n hoër een in die middel, 'n laer een aan elke kant, en 'n vloer wat die twee duike verbind. Wat is hierdie klassieke vorm?","options":["'n Drievoudige bodem","'n Kop en skouers, 'n moontlike einde van die opwaartse neiging","'n Stygende driehoek","Drie hamers agtermekaar"]}},"63":{"title":"Die Driehoekknyp","desc":"Grafiekpatrone: die opgerolde veer","content":"Wanneer die swaaie aanhou krimp, hoër laagtepunte wat teen laer hoogtepunte opdruk, rol die mark op soos 'n veer. Dit is 'n driehoek: albei kante raak sonder ruimte, en 'n besluit word afgedwing. Die knyp eindig dikwels met 'n uitbarsting, en hier is die vangplek: die rigting van die uitbarsting is nie vooraf bekend nie. Wag vir die breek in plaas daarvan om dit te raai. Die mark sal jou sê, en dit vra niks vir die inligting nie. 🌀","quiz":{"q":"Die swaaie krimp aanhoudend en druk die prys in 'n al hoe stywer rol totdat dit uiteindelik uitbars. Wat was die rol?","options":["'n Kanaal, die lyne ontmoet nooit","'n Dubbeltop","'n Driehoek, 'n konsolidasie wat dikwels in 'n uitbraak eindig","Bewys dat die prys volgende op moes gaan"]}},"64":{"title":"Volume: die Leuenverklikker","desc":"Volume: wie werklik opgedaag het","content":"Volume is hoeveel aandele van hand verwissel het, en dit is die leuenverklikker van grafieke. 'n Uitbraak op piepklein volume is 'n gefluister wat mense mislei: 'n handjievol transaksies het die prys êrens gestoot waar dit nie kan bly nie. 'n Uitbraak op swaar volume is 'n skare wat werklik met geld stem. Dieselfde prysbeweging, heeltemal verskillende betekenis. Voor jy enige groot beweging glo, gaan kyk wie daarvoor opgedaag het. 🔊","quiz":{"q":"Twee ontsnappogings uit dieselfde plafon: die eerste op piepklein volume het misluk, die tweede het met enorme volume gekom en gehou. Wat doen volume hier?","options":["Niks, volume maak nooit saak nie","Dit dwing die prys op, hoë volume stoot pryse","Dit voorspel die presiese top van die beweging","Dit dien as bevestiging, groot volume wys werklike oortuiging agter die beweging"]}},"65":{"title":"Die Neigingherkenner","desc":"Tien grafieke, geen etikette, geen genade","content":"Tien grafieke. Geen etikette, geen hulplyne, geen wenke nie. Sê wat elkeen wys, presies soos 'n werklike handelaar wat na 'n werklike skerm staar. Kry 8 uit 10 en die module is joune. Jy kry een poging per dag, so vat dit stadig, lees die kerse, en onthou die belangrikste les van almal: soms is die eerlike antwoord dat daar glad nie 'n patroon is nie. 🕯️","bossVictory":"Neigingmodule verower. Jy lees nou die grafieke, die grafieke lees nie vir jou nie. 🕯️","bossQuestions":{"0":{"q":"Wat wys hierdie grafiek?","explanation":"Doelbewus deurmekaar. Haal die geraas uit en elke swaai-hoogtepunt klop steeds die vorige een, en elke duik eindig steeds hoër. Werklike neigings lyk so, nie soos 'n handboektrap nie.","options":["'n Afwaartse neiging, laer hoogtepunte en laer laagtepunte","'n Opwaartse neiging, hoër hoogtepunte en hoër laagtepunte","'n Sywaartse reeks","'n Dubbeltop"]},"1":{"q":"Wat het by die gloeiende paar kerse gebeur?","explanation":"Die rooi liggaam het die hele groen liggaam ingesluk net ná 'n lang klim. Dit is die bearish engulfing wat presies doen wat dit doen: opdaag waar kopers die meeste uitgerek is.","options":["'n Bullish engulfing","'n Doji aan die bopunt","'n Hamer","'n Bearish engulfing aan die bopunt van 'n opmars"]},"2":{"q":"Wat wys hierdie grafiek?","explanation":"Die middelste piek staan duidelik bo die twee aan weerskante, en die duike val in lyn as 'n neklyn. Werklikes is nooit simmetries nie, en dit is hoe hulle werklik in die natuur lyk.","options":["'n Kop en skouers","'n Drievoudige top met drie gelyke pieke","'n Stygende driehoek","'n Stygende kanaal"]},"3":{"q":"Wat wys hierdie grafiek?","explanation":"Twee toetse op dieselfde vloer, die tweede een effens vlakker, toe 'n stoot op deur die middelste bons. Die W-vorm, geteken deur 'n werklike mark eerder as deur 'n handboek.","options":["'n Kop en skouers","'n Dalende driehoek","'n Dubbelbodem","'n Beervlag"]},"4":{"q":"Wat is die gloeiende kers?","explanation":"Lang boonste wiek, piepklein liggaam wat aan die onderkant van die reeks geparkeer is, reg ná 'n opmars. Kopers het na 'n nuwe hoogtepunt gereik en is voor die sluiting teruggeklap.","options":["'n Hamer","'n Groen marubozu","'n Doji","'n Vallende ster ná 'n klim"]},"5":{"q":"Wat wys hierdie grafiek?","explanation":"Dieselfde vloer en dieselfde plafon word aanhoudend gerespekteer, en alles tussenin is geraas. Nie een kant wen nie, so daar is geen neiging om te ry nie.","options":["'n Reeks, die prys is vasgekeer tussen steun en weerstand","'n Opwaartse neiging, hoër hoogtepunte en hoër laagtepunte","'n Dalende wig","'n Uitbraak wat besig is om te gebeur"]},"6":{"q":"Die prys het bo die ou plafon uitgebreek, toe kom die duik met die pyltjie terug na daardie vlak en hou. Wat was die duik?","explanation":"Die duik het presies teruggekeer na die vlak wat vroeër die plafon was, kopers daar gekry, en die neiging het voortgegaan. Dit is 'n terugtrek. 'n Omkeer sou deur die vlak gesny het en aanhou val het.","options":["'n Volle omkeer in 'n afwaartse neiging","'n Terugtrek, 'n hertoets van die gebreekte vlak","'n Dubbeltop","'n Dooiekat-bons"]},"7":{"q":"Wat wys hierdie grafiek?","explanation":"Plat vloer, laer hoogtepunte wat daarop afdruk, verkopers wat by elke bons vroeër opdaag. Die vloer het uiteindelik meegegee, wat die uitkoms is waarheen hierdie vorm dikwels neig. Dikwels, nooit altyd nie.","options":["'n Stygende driehoek","'n Stygende kanaal","'n Dalende driehoek wat op steun leun","'n Dubbelbodem"]},"8":{"q":"Wat wys hierdie grafiek?","explanation":"Die strikvraag, en die waardevolste een in die baas. Die meeste grafieke, die meeste van die tyd, wys niks wat die moeite werd is om te verhandel nie. Om patrone te sien wat nie daar is nie, is hoe beginners verloor. Om 'geen transaksie' te sê, is 'n vaardigheid. 🎯","options":["'n Kop en skouers","'n Dubbeltop","'n Opwaartse neiging","Geen skoon patroon nie, daar is niks verhandelbaar hier nie"]},"9":{"q":"Wat wys hierdie grafiek?","explanation":"Die prys het op flou volume bo die plafon uitgesteek, kopers het dit gejaag, toe stort dit reguit terug in die reeks. Die uitbraak wat misluk, is presies hoekom die volume-les jou gesê het om volume na te gaan voor jy een glo.","options":["'n Bulstrik, 'n mislukte uitbraak wat kopers ingesuig het","'n Suksesvolle uitbraak met 'n skoon hertoets","'n Dubbelbodem","'n Hamer-omkeer"]}}},"66":{"title":"Jy Besit Hier Niks","desc":"'n Afgeleide is 'n weddenskap op 'n syfer","content":"Alles wat jy tot dusver geleer het, het 'n ding daaragter gehad. Koop 'n aandeel in {retail} en jy besit 'n skyfie van die maatskappy: 'n skyfie van die winkels, 'n skyfie van die winste, 'n stem by die vergadering, en 'n dividend wanneer hulle een betaal.\\n\\n'n Afgeleide is nie dit nie.\\n\\n'n CFD (kontrak vir verskil) is 'n ooreenkoms tussen jou en 'n verskaffer om die verskil in 'n prys te ruil tussen wanneer jy oopmaak en wanneer jy sluit. Dit is die hele produk. As {retail} opgaan en jy het op 'op' gewed, betaal hulle jou die verskil. As dit afgaan, betaal jy hulle. Niemand koop 'n aandeel nie. Niemand verkoop 'n aandeel nie. Geen aandele bestaan enige plek in die transaksie nie.\\n\\n'n Termynkontrak is 'n kontrak om iets teen 'n vasgestelde prys op 'n vasgestelde datum te koop of te verkoop. Werklikes vereffen in werklike vate olie of tonne mielies, maar byna niemand hou hulle so lank nie, so in die praktyk is die meeste termynkontrakte ook 'n weddenskap op 'n syfer met 'n sperdatum daaraan geheg.\\n\\nHoekom dit meer saak maak as wat dit klink:\\n\\n• Geen dividende nie. Geen Geldbabas nie. Die ding wat stilweg die meeste van die opbrengste in les 15 gebou het, is eenvoudig nie hier nie.\\n• Geen stem, geen eienaarskap, niks om te hou nie. Daar is geen \\"hou dit net tien jaar lank\\"-opsie nie, want daar is niks om te hou nie.\\n• Geen saamgestelde groei nie. Die res van hierdie app spandeer 65 lesse om jou te leer dat tyd aan jou kant is. In hierdie kamer kos tyd jou geld. Jy sal in les 72 presies sien hoeveel.\\n\\nAlles wat jy reeds weet, maak steeds saak. Dit hou net op om die ding te wees wat jy doen. 📄","quiz":{"q":"Jy maak 'n CFD op {retail} oop en die prys styg. Wat besit jy werklik?","options":["Aandele in {retail}, wat die verskaffer vir jou hou","'n Aandeel in {retail} plus die reg op enige dividend wat dit betaal","Niks. Jy hou 'n kontrak om die prysverskil te ruil, en geen aandele verwissel van hand nie","'n Bewys wat in werklike aandele omskakel wanneer jy sluit"]}},"67":{"title":"Leen by 'n Vriend","desc":"Wat hefboom werklik is, en die deel wat niemand plaas nie","content":"Hefboom klink tegnies. Dit is nie. Dit is leen.\\n\\nSê nou jy wil {c}1,000 se aandele hê maar jy het net {c}200. 'n Vriend bied aan om die ander {c}800 in te sit. Jy beheer {c}1,000 se aandele met {c}200 van jou eie geld. Dit is hefboom. Dit is die hele idee.\\n\\nNou die drie dinge wat daardie vriend doen. Jy het al drie nodig, anders is 'n sprokie aan jou verkoop.\\n\\n1️⃣ DIE OPWAARTSE KANT IS WERKLIK JOUNE. Die aandele gaan 10% op. Jou {c}1,000 is nou {c}1,100. Dit is {c}100 se wins en jy hou elke sent daarvan, want jou vriend word {c}800 geskuld en nie 'n {cName} meer nie. Op jou eie {c}200 is {c}100 'n wins van 50%. 'n Beweging van 10% het jou 50% gemaak. Dit is die deel waaroor almal plaas.\\n\\n2️⃣ DIE LENING KRIMP NIE WANNEER JY VERKEERD IS NIE. Dit is die deel waaroor niemand plaas nie, en dit is die hele les. Die aandele val eerder 10%. Jou {c}1,000 is nou {c}900. Jy skuld jou vriend steeds die volle {c}800. Nie {c}720 nie. Die volle {c}800. So die hele val van {c}100 kom uit JOU deel, en jou {c}200 is nou {c}100. 'n Beweging van 10% het jou 50% gekos.\\n\\nLees daardie twee weer. Dieselfde vriend, dieselfde 10%. Jou geld beweeg teen vyf keer die spoed in albei rigtings, want die lening vat nooit 'n deel van die pyn nie.\\n\\n3️⃣ DIE VRIEND VRA HUUR, DAAGLIKS, OP DIE HELE DING. Nie op hulle {c}800 nie. Op die volle {c}1,000 wat jy beheer. Elke nag wat jy dit hou, of die prys op, af of glad nêrens gegaan het.\\n\\nEn daar is 'n vierde ding wat binne die derde skuil. As jou {c}200 min raak, bel jou vriend jou nie om dit te bespreek nie. Hulle verkoop. Onmiddellik, outomaties, teen watter prys ook al beskikbaar is, want dit is hulle {c}800 wat op die spel is en hulle wag nie vir jou mening nie. Dit het 'n naam, en jy ontmoet dit oor drie lesse: likwidasie.\\n\\nSo: groter winste, groter verliese, huur elke nag, en iemand anders se vinger op die verkoopknoppie. Hefboom is nie gratis geld met 'n bietjie risiko aangeheg nie. Dit is 'n lening met al vier daardie dinge aangeheg, en die advertensies wys jou net ooit die eerste een. 🧠","quiz":{"q":"Jou vriend sit {c}800 in, jy sit {c}200 in, en saam beheer julle {c}1,000 se aandele. Die aandele val 10%. Wat gebeur met jou {c}200?","options":["Dit val tot {c}100, want die lening van {c}800 krimp nie en die hele val van {c}100 kom uit jou deel","Dit val tot {c}180, want jy besit net 'n vyfde van die posisie","Dit bly {c}200, want jou vriend absorbeer die val op hulle groter aandeel","Dit val tot {c}190, want verliese word gedeel in verhouding tot wat elkeen van julle ingesit het"]}},"68":{"title":"Marge is 'n Deposito, nie 'n Aankoop nie","desc":"Die geld wat jy neersit is nie bestee nie, dit is op die spel","content":"Wanneer jy 'n aandeel vir {c}100 koop, is daardie {c}100 uit jou kontant weg en sit 'n aandeel in jou rekening. 'n Eenvoudige ruil.\\n\\nMarge werk nie so nie. Wanneer jy 'n hefboomposisie oopmaak, sit jy 'n deposito neer, en daardie deposito is nie 'n betaling vir enigiets nie. Dit is 'n sekuriteitsdeposito teen jou eie verliese. Dit sit daar, gesluit, en die posisie eet dit op soos die prys teen jou beweeg.\\n\\nSê nou die depositokoers is 25%. Jy sit 250 NT neer en jy beheer 1,000 NT se blootstelling. Kyk na jou rekening:\\n\\n• Prys plat: jou 250 is steeds 250. Behalwe dat finansiering begin het, so dit is stilweg minder.\\n• Prys 5% af: die posisie het 50 NT verloor. Jou deposito is effektief 200. Jou vry kontant het nie beweeg nie. Jou rekening is kleiner.\\n• Prys 20% af: die posisie het 200 NT verloor. Jou deposito is af tot 50. Jy het niks gedoen nie. Jy het niks verkoop nie. Jy het gekyk.\\n\\nDrie woorde wat op elke skerm in hierdie kamer sit:\\n\\n🔒 GEBRUIKTE MARGE: elke deposito wat jy tans geplaas het.\\n💰 REKENINGEKWITEIT: jou vry kontant, plus jou geplaaste marge, plus of minus elke oop posisie se wins en verlies, minus die finansiering wat tot dusver gehef is. Wat jou rekening werklik werd is as alles nou toemaak.\\n📊 MARGEVLAK: ekwiteit gedeel deur gebruikte marge. Bo 100% het jy 'n kussing. Onder 100% het die mark die kussing klaargemaak en op die deposito begin.\\n\\nEn een reël wat almal verras: marge word oor jou hele rekening gemeet, nie per posisie nie. 'n Verloorposisie eet die kollateraal wat 'n wenner regop hou. Dit is hoekom \\"my ander transaksie is reg\\" nie 'n verweer is nie. 🔒","quiz":{"q":"Jy plaas 'n deposito van 250 NT om 1,000 NT se blootstelling te beheer. Die prys val 8% terwyl jy glad niks doen nie. Wat het gebeur?","options":["Nog niks, want 'n verlies tel eers wanneer jy die posisie sluit","Jy skuld 80 NT ekstra kontant, wat onmiddellik uit jou vry saldo geneem word","Jou deposito is onaangeraak, want 'n deposito is 'n betaling eerder as kollateraal","Die posisie het 80 NT verloor, jou deposito absorbeer dit, en jou rekeningekwiteit is 80 NT kleiner"]}},"69":{"title":"Die Margeversoek","desc":"'n Eis, nie 'n waarskuwing nie","content":"'n Margeversoek is die oomblik wanneer jou margevlak onder 100% val. In gewone woorde: jou winskussing is klaar en die mark het begin om die deposito self op te eet.\\n\\nHier is hoe dit werklik voel, want die handboekweergawe mis die belangrike deel.\\n\\nDit kom nooit op 'n goeie dag nie. Dit kom wanneer die posisie reeds lelik is, wanneer jy jouself reeds twee keer gesê het dit sal terugkom, en wanneer jy die minste in staat is om 'n kalm besluit te neem. Dit is nie 'n beleefde waarskuwing nie. Dit is 'n eis: sit meer geld in, of sluit posisies, of die verskaffer doen dit vir jou.\\n\\nJy het drie skuiwe en net twee daarvan is joune.\\n\\n1️⃣ SLUIT iets. Dit maak marge onmiddellik vry en dit is byna altyd die regte antwoord. Dit beteken ook om te erken jy was verkeerd, wat die werklike rede is waarom mense dit nie doen nie.\\n2️⃣ SIT geld by. Dit los niks op nie. Dit koop vir jou ruimte om langer verkeerd te wees, op 'n posisie wat jy reeds sleg gekies het, met geld wat jy nie beplan het om te waag nie. Om kontant by 'n margeversoek by te sit, is hoe 'n slegte transaksie 'n slegte maand word.\\n3️⃣ DOEN NIKS. Dan gebeur die derde skuif sonder jou, en dit het 'n naam.\\n\\nReguleerders vat dit so ernstig op dat hulle 'n syfer in die wet geskryf het. Firmas in Europa, die VK en Australië moet 'n kleinhandelkliënt se posisies outomaties sluit wanneer hulle marge tot 50% van wat vereis is val. Nie 'behoort' nie. Moet. Hulle het daardie reël geskryf omdat mense, toe hulle self kon besluit, opsie 3 gekies het en meer verloor het as wat hulle gehad het. ⚠️","quiz":{"q":"Jou margevlak het tot 80% geval en jy is in 'n margeversoek. Watter reaksie verminder werklik die risiko van likwidasie, in plaas daarvan om dit net uit te stel?","options":["Om meer kontant te deponeer, sodat die posisie ruimte het om te herstel","Om 'n posisie te sluit, wat die marge wat dit gebruik het dadelik vrymaak","Om te wag, want margevlakke herstel gewoonlik vanself","Om 'n tweede posisie in die teenoorgestelde rigting oop te maak om dit uit te kanselleer"]}},"70":{"title":"Likwidasie, en die Prys wat Jy Eerste Moet Ken","desc":"Die presiese prys waar jou rekening nul tref","content":"Likwidasie is wanneer die verskaffer jou posisies vir jou sluit omdat jou deposito byna op is. Dit is outomaties. Dit is oombliklik. Niemand vra jou mening nie, niemand kyk of jy op die punt was om reg te wees nie, en daar is geen appèl nie.\\n\\nDie enkele nuttigste syfer in hierdie hele module is jou LIKWIDASIEPRYS: die werklike prys, in werklike {cPlural}, waar dit gebeur.\\n\\nNie 'n persentasie nie. 'n Prys. Want 'jy kan jou deposito verloor' is 'n sin waarvoor jy kan knik en dit dan vergeet, terwyl '{tech} teen {c}87.40 en jou rekening is leeg' 'n feit is wat jy teen die grafiek kan nagaan voor jy op enigiets druk.\\n\\nElke skerm in hierdie kamer wys dit voor jy bevestig, geteken op dieselfde prysskaal as die grafiek sodat jy kan sien hoe ver dit werklik is. Twee dinge sal jou onmiddellik opval, en albei is die les:\\n\\n📏 'n Groter deposito stoot die likwidasieprys verder weg. Meer van jou eie geld in beteken die prys moet verder val voor jou geld op is.\\n⚡ 'n Kleiner deposito sleep dit tot reg langs vandag se prys. Teen 'n deposito van 10% is likwidasie omtrent 'n beweging van 10% weg, en 'n beweging van 10% is 'n doodgewone week.\\n\\nDan die eerlike vangplek. Die likwidasieprys is waar die enjin jou wil sluit, nie waar jy gewaarborg is om uit te kom nie. As slegte nuus oornag land en die mark ver onder daardie vlak heropen, word jy gesluit teen wat die mark werklik gaan betaal. Dit is die gaping, en les 78 gaan daaroor.\\n\\nKen jou likwidasieprys voor jy oopmaak. As jy dit nie hardop kan sê nie, verstaan jy nie die transaksie wat jy op die punt is om te doen nie. 💀","quiz":{"q":"Hoekom laat die app jou na 'n likwidasieprys in {cPlural} kyk, in plaas daarvan om jou net te waarsku dat hefboom riskant is?","options":["Omdat 'n werklike prys iets is wat jy teen die grafiek kan nagaan en beoordeel, terwyl 'n algemene waarskuwing maklik is om voor te knik en te ignoreer","Omdat die likwidasieprys deur die beurs vasgestel word en nooit kan verander nie","Omdat om die syfer te ken waarborg dat jy presies teen daardie prys gesluit sal word","Omdat die likwidasieprys jou vertel hoeveel wins die posisie gaan maak"]}},"71":{"title":"Die Pad Terug is Steiler","desc":"Hoekom verliese moeiliker is om ongedaan te maak as wat hulle lyk","content":"Verliese en winste voel soos teenoorgesteldes. Hulle is nie, en die wiskunde is nie eers naby nie.\\n\\nVerloor 10%? Jy het +11% nodig om terug te kom. Irriterend, maar oukei.\\nVerloor 50%? Jy het +100% nodig. Jy moet VERDUBBEL net om gelyk te breek.\\nVerloor 75%? Jy het +300% nodig.\\nVerloor 90%? Jy het +900% nodig.\\n\\nDie rede is eenvoudig sodra jy dit sien: die wins word bereken op die kleiner hoop wat jy oorhet. 100 val tot 50, en om van 50 terug tot 100 te klim moet daardie kleiner hoop verdubbel.\\n\\nVoeg nou hefboom by, en let op wat dit werklik doen. Dit maak nie net jou winste vinniger nie. Dit skuif jou in een middag af in daardie tabel. 'n Val van 12% in 'n aandeel, wat 'n slegte maar heeltemal normale week is, is 'n slag van 48% vir jou rekening teen 'n deposito van 25%. Jy het nou +92% nodig om terug te wees waar jy begin het, ná 'n week wat skaars die nuus gehaal het.\\n\\nDit is hoekom professionele mense oor kapitaalbeskerming praat voordat hulle oor enigiets anders praat, en hoekom \\"ek sal dit terugmaak\\" die duurste sin in verhandeling is. Om dit terug te maak is rekenkundig moeiliker as wat dit was om dit te verloor, elke enkele keer. ⛰️","quiz":{"q":"Jou rekening is 75% af. Watter opbrengs het jy van hier af nodig net om terug te kom waar jy begin het?","options":["75%, dieselfde persentasie wat jy verloor het","100%, want jy moet verdubbel","150%, een en 'n half keer die val","300%, want die klim word bereken op die veel kleiner hoop wat jy oorhet"]}},"72":{"title":"Die Huur op Geleende Geld","desc":"Reg oor die rigting, en steeds onder op die transaksie","content":"Jy het die blootstelling geleen. So jy betaal daarvoor. Elke nag.\\n\\nFinansiering (party plekke noem dit 'n swap, of 'n oornagfooi) word daagliks gehef, en hier is die deel wat almal vang: dit word op die VOLLE posisie gehef, nie op die deel wat jy geleen het nie. Sit 500 NT neer om 2,000 NT te beheer en jy betaal huur op 2,000.\\n\\nHoe dit uitgewerk word: 'n maatstafrentekoers, plus die verskaffer se opslag, gedeel deur 365, maal jou volle posisie. Jy sien albei helftes op die skerm in hierdie app, want 'n fooi wat jy nie uitmekaar kan haal nie, is 'n fooi wat jy nie kan beoordeel nie. Teen omtrent 7.3% per jaar kom dit op sowat 0.02% van jou posisie per nag neer.\\n\\nKlink na niks. Kyk nou hoe dit 'n wentransaksie opeet. 🧾\\n\\nDIE TRANSAKSIE WAT JY REG KRY EN STEEDS VERLOOR\\n\\nJy maak 'n posisie van 2,000 NT op {retail} oop met 'n deposito van 500 NT. Jy is bullish, en jy blyk reg te wees: oor die volgende paar maande dryf {retail} 2% OP.\\n\\n• Jou wins: 2% van 2,000 = 40 NT. Op 'n deposito van 500 NT is dit +8%. Lekker.\\n• Jou huur: 0.02% van 2,000 = 0.40 NT, elke nag.\\n\\nNag 50: jy het 20 NT betaal. Jy is altesaam 20 NT op. Jy wen steeds.\\nNag 100: jy het 40 NT betaal. Jou 40 NT se wins is nou presies nul werd. Jy was reg en jy het niks gemaak nie.\\nNag 180: jy het 72 NT betaal. Jou wins is steeds 40 NT. Jy is 32 NT AF, wat minus 6.4% van jou deposito is, op 'n transaksie waar jy die mark ses maande lank korrek gelees het.\\n\\nLees dit weer. Die prys het gedoen wat jy gesê het dit sou. Jy het steeds verloor.\\n\\nDit is die sin om uit hierdie les te vat: op 'n hefboomposisie het dit 'n vervaldatum om reg te wees. In hierdie voorbeeld is dit 100 nagte weg, en jy kan joune uitwerk voor jy oopmaak. Deel die wins waarop jy hoop deur die nagtelike huur. Dit is hoeveel nagte jou mening werd is.\\n\\nDie teenoorgestelde is ook opmerklik. Die res van hierdie app leer saamgestelde groei, waar tyd stilweg vir jou geld maak terwyl jy slaap. Dit is dieselfde masjien, wat agteruit loop, op jou gerig. ⏳","quiz":{"q":"Jy hou 'n hefboomposisie van 2,000 NT wat 0.40 NT per nag aan finansiering kos. Die prys styg genoeg om jou 'n wins van 40 NT te gee, en hou dan op beweeg. Ná hoeveel nagte is daardie wins heeltemal opgeëet?","options":["Dit word nooit opgeëet nie, want finansiering word net op die geleende deel gehef","Ongeveer 100 nagte, want 40 NT se wins gedeel deur 0.40 NT per nag is 100","Ongeveer 20 nagte, want finansiering word op jou deposito van 500 NT gehef","Finansiering word net gehef wanneer 'n posisie teen 'n verlies gesluit word"]}},"73":{"title":"Termynkontrakte: Die Klok en die Rol","desc":"Dieselfde koste, net anders afgelewer","content":"Termynkontrakte en CFD's is neefs. Albei is hefboom, albei gebruik marge, albei kan jou likwideer. Twee dinge maak termynkontrakte anders, en die tweede is die interessante een.\\n\\n⏰ 1. DAAR IS 'N DATUM DAAROP. Elke termynkontrak verval. Maart-olie, Junie-mielies, September-indeks. Wanneer die datum aanbreek, vereffen die kontrak en hou op bestaan. 'Hou vas en wag dat dit terugkom' is eenvoudig nie op die spyskaart nie, want die kontrak sal nie daar wees nie. 'n CFD verval nooit, wat beter klink totdat jy onthou dit vra vir altyd huur.\\n\\n🔄 2. DIE KOSTE IS IN DIE PRYS INGEBOU, NIE NAGTELIKS GEFAKTUREER NIE. Dit is die deel wat mense mis. 'n Termynkontrak vra jou gewoonlik nie 'n nagtelike finansieringsfooi nie. In plaas daarvan is die koste om die ding tot daardie datum te hou reeds in die kontrak se prys ingebak. Kontrakte vir later datums kos dikwels meer as kontrakte vir vroeër datums, en daardie gaping is dieselfde draagkoste wat binne die syfer sit.\\n\\nSo wat gebeur wanneer 'n handelaar die posisie ná verval wil hou? Hulle ROL: sluit die vervallende kontrak, maak die volgende een oop. En as die volgende een duurder is, betaal hulle daardie verskil. Elke rol. Dit is die CFD se nagtelike huur, ingevorder in groter, minder gereelde paaiemente.\\n\\nDie eerlike opsomming:\\n\\n• CFD: geen sperdatum, huur elke nag, uitgesplits op jou staat.\\n• Termynkontrak: harde sperdatum, koste versteek binne die prys en betaal by elke rol, maklik om te mis.\\n\\nNie een is gratis nie. Een van hulle bied net die rekening beleefder aan, en 'n koste wat jy nie kan sien nie, is die een wat jou heel waarskynlik gaan verras. ⏳","quiz":{"q":"'n Handelaar wil 'n termynposisie ná sy vervaldatum hou, en die volgende kontrak verhandel duurder as die een wat verval. Wat gebeur wanneer hulle rol?","options":["Niks, want rol is een gekombineerde transaksie en is gratis","Hulle ontvang die prysverskil, want later kontrakte is meer werd","Hulle betaal die verskil, wat dieselfde houkoste is wat 'n CFD hulle nagteliks sou gehef het","Die posisie skakel outomaties oor na 'n CFD sonder verval"]}},"74":{"title":"Kort Gaan: Die Verlies Sonder 'n Vloer","desc":"Hoekom die afwaartse weddenskap geen natuurlike plafon het nie","content":"Alles in hierdie app tot dusver was lank: jy koop, jy wil hê die prys moet opgaan. Afgeleides laat jou toe om kort te gaan, wat beteken om te wed dat die prys val. Jy maak 'n kortposisie oop, die prys val, jy maak wins.\\n\\nKort gaan is werklik nuttig en dit is nie boos nie. Dit is hoe 'n boer 'n prys vasmaak voor die oes en hoe 'n fonds 'n portefeulje beskerm. Om dit te verstaan maak jou beter daarmee om markte te lees, want vir die eerste keer sien jy albei kante van elke transaksie.\\n\\nMaar daar is een stukkie rekenkunde in kort gaan wat nêrens anders 'n ekwivalent het nie, en jy moet dit ingebrand kry.\\n\\n📉 WANNEER JY KOOP is jou ergste geval dat die prys tot nul gaan. Jy verloor 100% van wat jy ingesit het. Verskriklik, maar dit is 'n vloer. Daar is 'n bodem.\\n📈 WANNEER JY KORT GAAN, beteken die prys wat teen jou beweeg dat die prys OPgaan. En daar is nêrens 'n reël wat sê hoe hoog 'n prys toegelaat word om te gaan nie. 'n Aandeel wat verdriedubbel kos jou 200% van die posisie. 'n Aandeel wat tien keer opgaan kos jou 900%.\\n\\nLangverliese het 'n vloer. Kortverliese het nie. Daardie asimmetrie is die hele waarskuwing.\\n\\nWerklike markte doen dit. So nou en dan skiet 'n aandeel wat swaar geshort is op, want almal wat kort is, word gedwing om te koop om te sluit, wat die prys hoër stoot, wat nog meer van hulle dwing om te koop. Dit word 'n short squeeze genoem en dit het al fondse beëindig.\\n\\nTwee dinge hou jou lewend. Eerstens, 'n kortposisie is presies waar 'n stop-verlies ophou om opsioneel te wees. Tweedens, negatiewe saldo-beskerming: op 'n behoorlik gereguleerde kleinhandelrekening, en in hierdie app, kan jou rekening nie onder nul gaan nie. Jy kan alles verloor wat jy ingesit het. Jy kan nie eindig met skuld nie. Daardie beskerming bestaan omdat mense, voordat dit daar was, wel geëindig het met skuld. 🕳️","quiz":{"q":"Hoekom is die ergste geval op 'n kortposisie in soort anders as die ergste geval op 'n langposisie?","options":["Dit is nie anders nie, albei is beperk tot die verlies van wat jy ingesit het","'n Kortposisie kan nie geld verloor terwyl 'n stop-verlies daarop gestel is nie","'n Kortposisie verloor stadiger, want pryse val vinniger as wat hulle styg","'n Prys wat jy gekoop het kan net tot nul val, maar 'n prys wat jy geshort het het geen boonste grens wat dit verbied is om te bereik nie"]}},"75":{"title":"Wisselvalligheid Maal Hefboom","desc":"Hoekom kripto hier die grootste deposito nodig het","content":"Dieselfde vermenigvuldiger op twee verskillende bates is nie dieselfde weddenskap nie. Dit is die hele idee in hierdie les, en dit is hoekom die deposito wat jy moet neersit verander na gelang van wat jy verhandel.\\n\\nDink aan hoe 'n normale dag lyk:\\n• 'n Groot indeks beweeg op die meeste dae onder 1%.\\n• 'n Enkele aandeel beweeg dalk 2% of 3%.\\n• Kripto beweeg gereeld 5% of 10%, en 'n dag van 20% is nie 'n krisis nie, dit is 'n Dinsdag. 🎢\\n\\nSit nou 'n klein deposito agter elkeen daarvan. Teen 'n deposito van 10% vee 'n beweging van 10% jou uit. Vir die indeks is dit iets wat een keer in jare gebeur. Vir kripto is dit omtrent maandeliks. Dieselfde deposito. Heeltemal verskillende oorlewingskanse.\\n\\nReguleerders het dit uitgewerk en dit in die reëls geskryf. Toe ESMA in Maart 2018 CFD-hefboom oor Europa beperk het, het dit nie een syfer gekies nie. Dit het hulle in vlakke verdeel: 30:1 op hoofvalutapare, 20:1 op goud en hoofindekse, 10:1 op ander kommoditeite, 5:1 op individuele aandele, en heel onderaan, 2:1 op kripto. Twee tot een beteken 'n deposito van 50%. Vir kripto het hulle die HELFTE van die posisie in werklike geld geëis, die strengste koers op die hele lys.\\n\\nHierdie app doen dieselfde ding, om dieselfde rede, en dit sê dit op die skerm in plaas van om dit weg te steek:\\n\\n💱 Forex: die kleinste deposito, want hoofpare beweeg die minste.\\n🥇 Goud en kommoditeite: groter.\\n📊 Aandele, indekse en ETF's: nog groter.\\n🪙 Kripto: die grootste deposito van almal, want kripto beweeg die hardste.\\n\\nKripto word hier nie verban nie, en dit is doelbewus. Jy kan dit verhandel. Jy kan dit net nie op 'n dun deposito verhandel nie, want op 'n dun deposito sou 'n doodgewone kriptodag jou rekening beëindig het voordat jy klaar daaroor gelees het. Die groter deposito is nie die app wat snaaks is oor kripto nie. Dit is die app wat seker maak 'n normale dag kan jou nie doodmaak nie.\\n\\nDie moeite werd om te weet: die Britse reguleerder het verder as 'n vlak gegaan. In 2021 het dit kripto-afgeleides vir kleinhandelkliënte heeltemal verbied, met 'n skatting dat verbruikers omtrent £53 miljoen sou spaar. Jy kan kripto-hefboom hier ontmoet, met kastige geld en 'n vet deposito, of jy kan dit op agtien ontmoet met werklike geld en glad geen waarskuwing nie. Hierdie is die beter volgorde. 🌡️","quiz":{"q":"Kripto vereis die grootste deposito van enige bate in hierdie kamer. Wat is die werklike rede?","options":["Kripto is verban vir onder-18's, so die deposito dien as 'n straf","Kripto beweeg die hardste, so 'n dun deposito sou deur 'n heeltemal doodgewone dag uitgevee word","Kripto-posisies word geen finansiering gehef nie, so die deposito vervang dit","Kripto-pryse word deur die app gestel eerder as deur die mark"]}},"76":{"title":"Die Syfers wat Niemand Adverteer nie","desc":"Wat reguleerders gevind het toe hulle getel het","content":"Jy sal hierdie syfers nooit in 'n advertensie sien nie. Hulle kom van finansiële reguleerders, wat die werklike rekeningdata by die firmas kan eis, en wat dan publiseer wat hulle gevind het.\\n\\n🇪🇺 ESMA, die Europese reguleerder, Maart 2018. Oor EU-lande heen verloor tussen 74% en 89% van kleinhandel-CFD-rekeninge geld. Gemiddelde verliese per kliënt het gewissel van €1,600 tot €29,000. ESMA het die produk op grond daarvan beperk.\\n\\n🇬🇧 Die FCA in die VK, Desember 2016. Sy ontleding van 'n verteenwoordigende steekproef van kliëntrekeninge het gevind dat 82% van kliënte geld op hierdie produkte verloor het.\\n\\n🇦🇺 ASIC in Australië, gepubliseer in Januarie 2026, die mees onlangse van die drie. In die 2024-finansiële jaar het 68% van kleinhandel-CFD-beleggers geld verloor, altesaam meer as A$458 miljoen. Daarvan was A$73 miljoen fooie.\\n\\nSit 'n oomblik met daardie laaste reël. Drie-en-sewentig miljoen daarvan was nie eens slegte transaksies nie. Dit was die koste om te speel: die spreiding op pad in, en die finansiering wat jy in les 72 ontmoet het.\\n\\nDrie verskillende reguleerders, drie verskillende lande, data oor drie verskillende dekades, en die antwoord land oor en oor iewers tussen twee derdes en nege tiendes.\\n\\nNou die deel wat die meeste saak maak, want dit is wat keer dat dit net 'n skrikstatistiek is. Daardie mense was nie dom nie. Hulle was nie lui nie. Hulle was meestal grootmense met werk, en baie van hulle lees 'n grafiek beter as wat jy nou doen. Hulle het verloor oor hoe die produk gebou is: jy begin agter met die spreiding, jy betaal huur terwyl jy wag, en hefboom beteken 'n doodgewone beweging kan jou beëindig voordat jou mening tyd gehad het om reg te wees.\\n\\nDit is 'n struktuur, nie 'n karakterfout nie. En strukture kan net geklop word deur mense wat weet hulle is daar. 📊","quiz":{"q":"Reguleerders in Europa, die VK en Australië het elkeen gevind dat die meeste kleinhandel-CFD-rekeninge geld verloor. Wat is die eerlike verduideliking?","options":["Die mense wat verloor het was onversigtig, en versigtige handelaars word nie geraak nie","Die syfers is bemarking wat deur mededingende beleggingsfirmas uitgereik is","Die produk is so gebou dat die spreiding, die finansiering en die hefboom teen jou werk voordat jou siening tyd het om reg te wees","Verliese gebeur net in lande waar CFD's ongereguleer is"]}},"77":{"title":"Wat Verander Het Toe die Reëls Verander Het","desc":"Bewys dat dit die ontwerp was, nie die mense nie","content":"Les 76 het jou die verliese gegee. Hierdie les gee jou die eksperiment, en dit is die belangrikste ding in hierdie module.\\n\\nAs die meeste mense verloor omdat die meeste mense roekeloos is, dan behoort 'n verandering aan die reëls niks te verander nie. Die roekeloses bly roekeloos. Reg?\\n\\nAustralië het die toets gedoen. In Maart 2021 het ASIC 'n stel beskermings op elke CFD-firma afgedwing wat kleinhandelkliënte bedien: hefboomlimiete, 'n standaard outomatiese uitsluitreël, negatiewe saldo-beskerming, en 'n verbod op lokmiddels soos aanmeldbonusse. Dieselfde kliënte. Dieselfde firmas. Dieselfde markte. Net die reëls het verander.\\n\\nHier is wat ASIC in die eerste ses maande gemeet het. 🔬\\n\\n📉 Totale netto verliese deur kleinhandelrekeninge het met 91% gedaal, van gemiddeld A$372 miljoen per kwartaal tot A$33 miljoen.\\n📉 51% minder verliesmakende kleinhandelrekeninge per kwartaal.\\n📉 87% minder marge-uitsluitings.\\n📉 88% minder negatiewe saldo-gebeurtenisse.\\n\\nNiemand het in ses maande slimmer geword nie. Die ontwerp het verander, en nege tiendes van die skade het saam daarmee verdwyn.\\n\\nTwee dinge volg, en jy behoort albei saam te dra.\\n\\nEerstens: wanneer jy op 'n hefboomtransaksie verloor, was baie van wat met jou gebeur het reeds in die produk ingebou voordat jy aangekom het. Dit is nie toestemming om onversigtig te wees nie. Dit is 'n rede om die ding te respekteer.\\n\\nTweedens, en dit is die nuttige helfte: die beskermings wat die werk gedoen het, is presies die gewoontes wat hierdie module jou geleer het. 'n Kleiner posisie. 'n Outomatiese uitgang. 'n Harde vloer op die skade. 'n Reguleerder moes daardie dinge op 'n hele bedryf afdwing om daardie 91% te kry. Jy kan hulle net kies. 🛡️","quiz":{"q":"Nadat Australië hefboomlimiete en outomatiese uitsluitings op CFD-firmas afgedwing het, het kleinhandelverliese in ses maande met 91% gedaal. Wat wys dit?","options":["Die meeste van die skade het gekom van hoe die produk ontwerp is, want niks aan die kliënte het verander nie","Australiese handelaars is meer gedissiplineerd as Europese handelaars","Hefboom word veilig sodra 'n reguleerder kyk","Die reëls het mense heeltemal gekeer om te verhandel, so niemand kon verloor nie"]}},"78":{"title":"Die Gaping wat oor Jou Stop Spring","desc":"'n Stop is 'n opdrag om te vertrek, nie 'n belowe prys nie","content":"Jy het stop-verliese reeds in les 19 ontmoet. Hier is wat hefboom aan hulle doen.\\n\\n'n Stop-verlies is 'n opdrag: \\"as die prys hierdie vlak bereik, kry my uit.\\" Dit is nie 'n kontrak oor die prys wat jy gaan kry nie. Dit sê vertrek. Dit sê nie vertrek presies hier nie.\\n\\nDie meeste van die tyd maak daardie onderskeid nie saak nie, want pryse beweeg in klein stappies en jou order vul naby jou vlak. Dan, party van die tyd, maak dit enorm saak.\\n\\n📰 Markte sluit. Nuus land om 11nm. Die mark heropen 8% laer as waar dit gesluit het, en dit het nooit teen enige van die pryse tussenin verhandel nie. Jou stop was in daardie gaping. Dit vuur af by die heropening en vul waar die mark werklik is, wat ver verby die vlak is wat jy gekies het.\\n\\nSonder hefboom is dit 'n slegte dag. Met hefboom kan dit die hele rekening wees, want as jou deposito dunner was as die gaping, gaan die gaping reguit deur jou likwidasieprys ook, en jy word gesluit onder die vlak wat die enjin bedoel het.\\n\\nDrie dinge om hiermee te doen, en nie een is ingewikkeld nie:\\n\\n1️⃣ Moenie 'n stop as 'n waarborg hanteer nie. Hanteer dit as 'n baie goeie gewoonte met een bekende swakheid.\\n2️⃣ Weet wanneer jou mark gesluit is en wat geskeduleer is. Maatskappyresultate, rentekoersbesluite en verkiesings is gapings met 'n dagboekinskrywing.\\n3️⃣ Kies jou grootte so dat 'n gaping jou nie kan beëindig nie. Dit is die werklike verdediging, en dit is die volgende les. 'n Stop beskerm jou teen die gewone. Posisiegrootte beskerm jou teen die ongewone, en die ongewone is wat mense werklik uitvee.\\n\\nEn dit is die moeite werd om te weet dat in hierdie app, soos op enige behoorlik gereguleerde kleinhandelrekening, negatiewe saldo-beskerming beteken 'n gaping kan jou nie onder nul vat nie. Jy kan die rekening verloor. Jy kan nie eindig met skuld nie. 📰","quiz":{"q":"Jy stel 'n stop-verlies op {c}90. Oornag land slegte nuus en die mark heropen op {c}78, sonder dat dit ooit tussenin verhandel het. Wat gebeur?","options":["Jy word teen {c}90 gevul, want 'n stop waarborg die prys wat jy gekies het","Jou stop vuur by die heropening af en vul naby {c}78, want 'n stop is 'n opdrag om te vertrek eerder as 'n belowe prys","Die order word gekanselleer, want die prys het by jou vlak verbygespring","Die verskaffer betaal jou die verskil tussen {c}90 en {c}78"]}},"79":{"title":"Grootte Eerste, Dan die Transaksie","desc":"Besluit wat jy kan verloor voordat jy besluit wat om te koop","content":"Hier is die ding wat mense wat hou onderskei van mense wat nie hou nie, en dit is amper vervelig.\\n\\nBeginners kies die transaksie, en werk dan uit hoeveel om in te sit. Professionele mense doen dit andersom. Hulle besluit eers wat hulle bereid is om te verloor, en laat dit besluit hoe groot die posisie mag wees.\\n\\nDie reël wat die meeste van hulle gebruik: waag 1% tot 2% van die rekening op enige enkele transaksie. Nie deponeer 1% nie. WAAG 1%, wat beteken dit is wat jy werklik verloor as jou stop getref word.\\n\\nHoe dit werk, in drie stappe:\\n\\n1️⃣ Kies jou maksimum verlies. 'n Rekening van 10,000 NT, waag 1%, dus 100 NT.\\n2️⃣ Kies waar jy verkeerd is. Jy sal uitgaan as die prys 5% van jou intrede af val.\\n3️⃣ Deel. 100 NT se aanvaarbare verlies, teen 'n stopafstand van 5%, beteken 'n posisie van 2,000 NT. Dit is jou grootte. Nie 'n gevoel nie. 'n Berekening.\\n\\nVerander die stop en die grootte verander outomaties. 'n Nouer stop van 2% laat jou 5,000 NT loop. 'n Wyer stop van 10% dwing jou af tot 1,000 NT. Hoe riskanter die transaksie, hoe kleiner moet dit wees, en die rekenkunde doen dit vir jou sodat jou bui dit nie hoef te doen nie.\\n\\nHoekom 1%? Want dit maak 'n verloorreeks oorleefbaar. Tien verliese agtermekaar teen 1% laat jou met 90% van jou rekening en 'n slegte bui. Tien verliese agtermekaar teen 20% laat jou met sowat 11% van jou rekening en geen pad terug nie, en jy weet reeds uit les 71 hoe steil daardie klim is.\\n\\nNiemand oorleef markte deur wenners te kies nie. Almal wat oorleef, doen dit deur seker te maak geen enkele verlies kan hulle beëindig nie. 📐","quiz":{"q":"Jy het 'n rekening van 10,000 NT, jy gaan 1% op 'n transaksie waag, en jy gaan uitgaan as die prys 5% van jou intrede af val. Hoe groot behoort die posisie te wees?","options":["100 NT, wat die 1% is wat jy waag","500 NT, wat 5% van die rekening is","2,000 NT, want 100 NT se aanvaarbare verlies gedeel deur 'n stopafstand van 5% gee die posisiegrootte","10,000 NT, want die stop beskerm in elk geval die hele rekening"]}},"80":{"title":"Hoekom Wen Soos Vaardigheid Voel","desc":"Die kopspeletjies wat hefboom met jou speel","content":"Hefboom is nie hoofsaaklik 'n wiskundeprobleem nie. Die wiskunde is maklik. Dit is 'n kopprobleem, en hier is die drie wat almal vang.\\n\\n🎯 1. UITKOMSSYDIGHEID: wen voel soos vaardigheid. Jy vat 'n waansinnig groot posisie, dit werk, jy maak baie in een middag, en jou brein skryf neer \\"ek is goed hierin.\\" Dit het nie opgeteken wat werklik gebeur het nie, naamlik dat jy 'n slegte risiko gevat het en 'n goeie uitkoms gekry het. Dit is verskillende dinge, en die mark sal jou gerus 'n paar keer vir 'n slegte besluit betaal voordat dit invorder. Die gevaarlikste ding wat met 'n nuwe handelaar kan gebeur, is 'n vroeë, maklike oorwinning.\\n\\n😤 2. WRAAKVERHANDELING: jy wil dit terughê, nou. Jy vat 'n verlies, dit brand, en die drang is onmiddellik. So jy maak groter. Jy sit nou jou grootste posisie op presies die oomblik wanneer jou oordeel op sy swakste is, op 'n transaksie wat jy gekies het omdat jy kwaad was eerder as omdat dit goed was. Die mark weet nie jy is af nie en skuld jou niks nie. Wanneer jy dit voel, is die korrekte grootte nul. Maak die app toe.\\n\\n🕳️ 3. VERLIESE JAAG: \\"ek hou net vas tot dit terugkom.\\" Hierdie een word as geduld aangetrek, en dit is hoekom dit so moeilik is om raak te sien. Geduld is 'n plan wat jy vooraf kalm gemaak het. Jaag is 'n plan wat jy uitgedink het nadat die prys teen jou gedraai het, en die teken is eenvoudig: jou uitgang het geskuif. As jy jouself hoor verduidelik hoekom die vlak wat jy gestel het nie meer die regte vlak is nie, is dit nie nuwe ontleding nie. Dit is jou ego wat onderhandel.\\n\\nDie verdediging vir al drie is dieselfde en dit is glansloos. Besluit alles terwyl jy kalm is, skryf dit neer, en hanteer die weergawe van jou wat middel-in-die-transaksie opdaag as 'n onbetroubare verteller. 🧠","quiz":{"q":"Jy vat 'n veel groter posisie as gewoonlik en dit maak 'n groot wins in een middag. Wat is die akkuraatste manier om dit te lees?","options":["Jy het 'n slegte risiko gevat en 'n goeie uitkoms gekry, wat twee afsonderlike dinge is, en 'n vroeë maklike oorwinning is die gevaarlikste ding wat met 'n nuwe handelaar kan gebeur","Jy het 'n benadering gevind wat werk en behoort volgende keer weer groter te maak","Die wins bewys die posisie se grootte was reg","Groot winste bevestig vaardigheid, want dit is verliese wat foute onthul"]}},"81":{"title":"Die Eerlike Vraag","desc":"Behoort jy dit hoegenaamd te gebruik?","content":"Jy het die module klaargemaak. Hier is die vraag wat die advertensies nooit vra nie.\\n\\nBehoort jy hefboom hoegenaamd te gebruik?\\n\\nVir die meeste mense, die meeste van die tyd, is die eerlike antwoord nee. Nie omdat hulle nie slim genoeg is nie. Weens alles in die laaste vyftien lesse: jy begin agter, jy betaal huur terwyl jy wag, 'n doodgewone beweging kan jou beëindig voordat jy reg bewys is, en drie reguleerders wat werklike rekeninge getel het, het oor en oor gevind dat twee derdes tot nege tiendes van mense verloor het.\\n\\nDaar is 'n weergawe van verhandeling waar jy nooit aan enigiets hiervan raak nie. Jy koop 'n aandeel, jy besit 'n stukkie van 'n maatskappy, dividende land, tyd werk VIR jou in plaas van teen jou, en niks kan ooit jou posisie sluit sonder om te vra nie. Dit is die res van hierdie app, en dit is nie die vervelige opsie nie. Dit is die opsie wat die wiskunde in les 14 sê gewoonlik wen. 🌱\\n\\nSo hier is wat jy behoort te weet voordat jy besluit.\\n\\nNiks in hierdie app is agter hefboom gesluit nie. Elke kompetisie, elke ranglys, elke XP-roete, elke skoolwedstryd en elke NOOB-beloning bly heeltemal oop vir iemand wat nooit 'n enkele hefboomposisie oopmaak nie. Jy verloor niks deur van hierdie kamer af weg te loop nie. Daar is geen straf en geen ontbrekende kenteken nie.\\n\\nEn niks hierin betaal jou om te wen nie. Jy word beloon vir die voltooiing van die lesse, vir die slaag van die toets, vir die stel van 'n stop, vir die afsny van 'n verloorder, en vir die uitskryf van jou eie likwidasie. Jy word nooit betaal vir 'n wins, 'n groot posisie of 'n gelukstreep nie, want om jou daarvoor te betaal sou beteken om jou die verkeerde ding te leer en dit onderwys te noem.\\n\\nAs jy dit gebruik: gebruik dit klein, gebruik dit met 'n stop, ken jou likwidasieprys voordat jy op enigiets druk, en nooit met geld wat jy sou mis nie. As jy dit nie gebruik nie, het jy steeds geleer om die masjinerie te sien, wat nog altyd die punt was. Die meeste grootmense wat hierdie goed verhandel kan nie verduidelik wat jy pas geleer het nie. 🤔","quiz":{"q":"Wat gee 'n leerder op deur te besluit om nooit 'n hefboomposisie in hierdie app oop te maak nie?","options":["Toegang tot kompetisies en ranglyste","Die XP uit hierdie module, wat net op hefboomtransaksies uitbetaal","NOOB-belonings, wat minstens een hefboomposisie vereis","Niks, want elke kompetisie, XP-roete en beloning bly hoe dan ook heeltemal oop"]}}}`),i={ZA:{name:"Suid-Afrika",cName:"rand",cPlural:"rand",exDesc:"een van die grootste aandelebeurse op die hele Afrika-vasteland",sectorList:`⛏️ Mynbou: Anglo American, Impala Platinum — gekoppel aan wêreldwye kommoditeitspryse
🏦 Bankwese: Standard Bank, FirstRand, Capitec — vaar goed wanneer rentekoerse hoër is
📱 Tegnologie: Naspers, Prosus — gekoppel aan wêreldwye tegnologieneigings
🛍️ Kleinhandel: Shoprite, Pick n Pay — vaar goed wanneer verbruikers geld het om te bestee
📡 Telekommunikasie: MTN, Vodacom — meer stabiel, mense het altyd data nodig`,etfBasket:"die 40 grootste maatskappye op die JSE",etfDesc:"Die JSE Top 40 is byvoorbeeld 'n lys van die 40 grootste JSE-genoteerde maatskappye, gerangskik volgens die waarde van die aandele wat werklik beskikbaar is om te verhandel.",etfList:`🇿🇦 Satrix Top 40: Die 40 grootste maatskappye op die JSE. Uitstekende beginpunt.
🌍 Satrix MSCI World: Maatskappye uit 23 ontwikkelde lande in een enkele aankoop.
🇺🇸 Sygnia Itrix S&P 500: Die 500 groot Amerikaanse maatskappye op die S&P 500-lys.
💡 Satrix Nasdaq 100: Die 100 grootste nie-finansiële maatskappye op Nasdaq — baie tegnologie-swaar.`,currencyHedge:"Hulle word in dollars of euro's geprys. So as die rand VERSWAK (R20 vir 'n dollar word R22), is jou wêreldwye beleggings OUTOMATIES meer werd in rand!",fxQuizSetup:"Die rand verswak van R18 na R22 teenoor die dollar",fxQuizLose:"Dit verloor waarde omdat dit slegter gaan met Suid-Afrika",fxQuizGain:"Dit gaan OP in randterme omdat elke dollar meer rand koop",dcaTitle:"Rand-kostemiddeling",dcaAbbrev:"RKM",food:"Wimpy-burger"}},a={_meta:e,lessons:n,context:i};export{e as _meta,i as context,a as default,n as lessons};
